(function(root){
  const part = {"spells":{"accelerate_step":{"name":"Accelerate Step","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Accelerate%20Step","src":"GM pg. 67","summary":"Drawing upon the Dimension of Time, you speed your steps until your every movement is a blur of motion. While you move up to your speed, charge, run, or step, you have concealment against attackers."},"accelerated_adaptation":{"name":"Accelerated Adaptation","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Accelerated%20Adaptation","src":"AP #29 pg. 44","summary":"You grant a barathu increased control over its own powers of adaptation. If the target has the early stage adaptation species trait, it gains adaptation instead. If the target already has adaptation, it can have two adaptations in effect at a time, instead of only one."},"acid_puddle":{"name":"Acid Puddle","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Acid%20Puddle","src":"GM pg. 67","summary":"You coat the area in conjured acid, which quickly pools on the ground. Creatures and objects in the area when the spell is cast take 6d6 acid damage. For the duration of the spell, creatures that enter or start their turn in the area take 2d6 acid damage."},"acid_rain":{"name":"Acid Rain","level":5,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Acid%20Rain","src":"COM pg. 133","summary":"You pull a downpour of elemental precipitation from an alternate reality. You then direct this acid rain to pour only onto your enemies, dealing them 3d6 acid damage each round. The acid splashes into and burns your foes’ eyes, coats them in slime, and clouds their other senses."},"acidic_mist":{"name":"Acidic Mist","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Acidic%20Mist","src":"NS pg. 154","summary":"You call forth the corrosive atmosphere of a gas giant to damage your opponents. A creature that starts its turn in the area takes 2d6 acid damage. The corrosive mist does not obscure vision."},"adamantine_shot":{"name":"Adamantine Shot","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Adamantine%20Shot","src":"GM pg. 67","summary":"Dwarves created adamantine shot to turn common ammunition into deadly projectiles with siege and mining potential. You transmute one longarm round or similar missile, such as an arrow, into a magical projectile that performs as adamantine alloy ammunition, then you launch it."},"adhere":{"name":"Adhere","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Adhere","src":"GM pg. 67","summary":"You create a molecular bond between an object you touch (bulk up to 1 + your caster level) and another object or a surface that object is touching."},"afterimage":{"name":"Afterimage","level":5,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Afterimage","src":"DC pg. 139","summary":"You instantly teleport from your current location to any other spot within range, be that a place you visualize or simply by deciding a direction and distance. You can bring along objects as long as their weight doesn’t exceed your maximum load."},"akashic_download":{"name":"Akashic Download","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Akashic%20Download","src":"AP #23 pg. 50","summary":"You do a cosmic search of the Akashic Record for information about a topic. Your tier 0 or better computer (such as a comm unit) instantly compiles snippets and selections from various media relevant to the subject. The information remains for 2 minutes, during which you explore it."},"akashic_investigation":{"name":"Akashic Investigation","level":6,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Akashic%20Investigation","src":"GM pg. 67","summary":"You sift through the Akashic Record to view a shadow of the past day’s events that happened in the spell’s area. You overlay these events at the location that they occurred, staging a blurred reenactment of events that took place over the last 24 hours."},"akashic_revival":{"name":"Akashic Revival","level":6,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Akashic%20Revival","src":"AP #23 pg. 50","summary":"You create perfect documentation of your physical body in the Akashic Record at the time the spell is cast, allowing you to later recall this record and reconstruct your body as it was when you cast this spell."},"akashic_tutor":{"name":"Akashic Tutor","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Akashic%20Tutor","src":"AP #30 pg. 52","summary":"You communicate with the Akashic Record of one of your classmates or former instructors, asking them to assist you in a task. When you cast this spell, select two skills; if you cast Akashic tutor more than once a day, you must select different skills each time."},"algae_bloom":{"name":"Algae Bloom","level":2,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Algae%20Bloom","src":"AP #36 pg. 51","summary":"You conjure a toxic algae bloom composed of particles that are sufficiently tiny to bypass standard environmental protections. Creatures that breathe (whether water or air) that start their turn in or enter the area must attempt a Fortitude save or become Sickened for 1d4+1 rounds."},"alter_corpse":{"name":"Alter Corpse","level":2,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Alter%20Corpse","src":"AP #25 pg. 45","summary":"You cause a corpse to change to suit a narrative you choose. This spell can hide or create clues about how the corpse ended up in its current state, from closing wounds to evaporating chemicals in the cadaver’s system."},"alter_enhancement":{"name":"Alter Enhancement","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Alter%20Enhancement","src":"NS pg. 155","summary":"You tap into the multiverse and find a reality with a forgotten object similar to the target of this spell, swapping that item with the target item."},"amorphous_form":{"name":"Amorphous Form","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Amorphous%20Form","src":"AP #27 pg. 45","summary":"Your body briefly shifts into an amorphous form, enabling you to circumvent certain attacks and squeeze through tight spaces. You do not take double damage from critical hits, but critical hit effects apply against you normally."},"anchor":{"name":"Anchor","level":2,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Anchor","src":"GM pg. 68","summary":"You conjure and attach a cable to an immobile object. When the spell ends, the cable returns to where it was summoned from. The cable has hardness 8, 8 Hit Points, and a length equal to the spell’s range. The cable can be pried free with an Athletics check equal to the spell’s DC."},"animate_armor":{"name":"Animate Armor","level":5,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Animate%20Armor","src":"AR pg. 156","summary":"You temporarily infuse a suit of armor with a magic force that allows it to move on its own and that directs its mechanisms. When you cast this spell, the armor acts and responds to your mental control for as long as you concentrate."},"animate_dead":{"name":"Animate Dead","level":4,"school":"nec","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Animate%20Dead","src":"CRB pg. 340","summary":"This spell turns corpses into undead creatures that obey your spoken commands. The undead can be made to follow you, or they can be made to remain in place and attack any creature (or a specific kind of creature) entering the area. They remain animated until they are destroyed."},"antimagic_burst":{"name":"Antimagic Burst","level":6,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Antimagic%20Burst","src":"GM pg. 68","summary":"You detonate a bubble of antimagic in the area, temporarily unraveling magical effects. This spell works like an area dispel from Dispel Magic, Greater, but your dispel check applies to every spell, supernatural effect, hybrid item, magic item, and magical effect in the area."},"antiradiation":{"name":"Antiradiation","level":3,"school":"abj","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Antiradiation","src":"COM pg. 133","summary":"You permeate radiation with mitigations from other realities, dissipating radiation effects in the spell’s area; the radiation level you affect depends on your caster level, as shown on the table below."},"aqueous_form":{"name":"Aqueous Form","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Aqueous%20Form","src":"AP #36 pg. 51","summary":"You temporarily transform part or all of your body into water, gaining unique abilities. 1st: When you cast aqueous form as a 1st-level spell, you gain a swim speed of 30 feet for 1 round, and changing direction while swimming doesn’t cost additional movement."},"arcane_eye":{"name":"Arcane Eye","level":4,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Arcane%20Eye","src":"CRB pg. 340","summary":"You create an invisible magical sensor that sends you visual information. The sensor appears at any point within line of sight, but it can then travel beyond your line of sight without hindrance."},"arcane_sight":{"name":"Arcane Sight","level":3,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Arcane%20Sight","src":"CRB pg. 340","summary":"This spell allows you to see magic sources within 120 feet of you. The effect is similar to that of a detect magic spell, but arcane sight does not require concentration and discerns information more quickly. You know the location and caster level of all magic sources within your sight."},"archive":{"name":"Archive","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Archive","src":"AP #32 pg. 53","summary":"You magically remove data from the target computer or module. You can remove an amount of data equal to what can be stored on a specific secure data module. You can end the spell with a swift action, restoring the missing data."},"arcing_surge":{"name":"Arcing Surge","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Arcing%20Surge","src":"CRB pg. 340","summary":"You cause an electrical device in your possession to surge in power and unleash a line of electricity from the massive oversurge. This deals 10d6 electricity damage to all creatures and objects in the area."},"artificial_geyser":{"name":"Artificial Geyser","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Artificial%20Geyser","src":"IS pg. 115","summary":"You create a burst of pressurized boiling water. This deals 3d8 slashing and fire damage and applies the Burning condition for 1d6 to each creature in the area. A successful Reflex save halves this damage and negates the burn condition."},"atavistic_howl":{"name":"Atavistic Howl","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Atavistic%20Howl","src":"AP #29 pg. 44","summary":"You release a howl of primal rage, echoing the pain of Dreamers awoken by injury. Creatures in the area that fail their saves are Shaken for 2d4 rounds. Dreamers are immune to this spell. Barathus can cast this spell as a reaction when reduced to 0 Hit Points."},"augury":{"name":"Augury","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Augury","src":"CRB pg. 340","summary":"Casting augury can tell you whether a particular action will bring good or bad results for you in the immediate future. Casting this spell takes intense personal focus and requires you to spend 1 Resolve Point."},"auto-cam":{"name":"Auto-Cam","level":1,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Auto-Cam","src":"EN pg. 119","summary":"You manifest an invisible and intangible sensor that hovers one foot above your head. The sensor records anything it can see and hear in a 30-foot radius with no special senses."},"autopilot":{"name":"Autopilot","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Autopilot","src":"GM pg. 68","summary":"You install an AI into a vehicle that can control the vehicle in place of an actual pilot. During the spell’s duration, you can engage or disengage the autopilot AI as a swift action."},"awaken_computer":{"name":"Awaken Computer","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Awaken%20Computer","src":"COM pg. 133","summary":"You infuse a computer with a spark of advanced technology, granting it an artificial personality. For this spell to take effect, you must have access to the computer, through either hacking it and bypassing any countermeasures it has or having unsecured access, but you don’t need root access."},"baleful_polymorph":{"name":"Baleful Polymorph","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Baleful%20Polymorph","src":"AA2 pg. 147","summary":"You change a target’s shape to that of a smaller, weaker creature. 1st: The target shrinks slightly (though it retains its size category) and gains a few cosmetic bestial features of an animal you choose."},"baleful_polymorph_mass":{"name":"Baleful Polymorph, Mass","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Baleful%20Polymorph%2C%20Mass","src":"AA2 pg. 148","summary":"This spell functions as Baleful Polymorph, except as noted in this description. Each target must take the same form. 4th: This spell causes all targets to suffer the effects of the 1st-level version of baleful polymorph."},"battle_junkbot":{"name":"Battle Junkbot","level":6,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Battle%20Junkbot","src":"CRB pg. 341","summary":"You turn a pile of technological junk into a vicious robot that can hunt down and attack your enemies. You must target inert, nonworking electronic equipment of at least 1 bulk."},"battle_sonata":{"name":"Battle Sonata","level":3,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Battle%20Sonata","src":"GM pg. 68","summary":"Employed to great effect by the pahtra defenders of independent Pulonis, this spell weaponizes music to devastate foes. You compose a deadly song that unleashes dissonant chords in a cone-shaped burst in front of you, dealing 8d6 sonic damage to all creatures and objects in the area."},"battlemind_link":{"name":"Battlemind Link","level":5,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Battlemind%20Link","src":"AP #20 pg. 45","summary":"You create a strong temporary psychic link between two creatures that allows them to act almost as one. This spell works like Battlemind Link, Lesser, but the enhancement bonus to initiative rolls is +4, and the spell ends if the targets are more than 500 feet apart, rather than 200 feet apart."},"battlemind_link_lesser":{"name":"Battlemind Link, Lesser","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Battlemind%20Link%2C%20Lesser","src":"AP #20 pg. 45","summary":"You form a temporary psychic link between two creatures that allows them to act almost as one. While this spell is active, the two targets each roll initiative in combat and use the higher die result between them before adding modifiers."},"bend_reality":{"name":"Bend Reality","level":5,"school":"uni","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Bend%20Reality","src":"EN pg. 119","summary":"You become a conduit for all possible realities and timelines, enabling you to twist events with little warning."},"benevolent_synesthesia":{"name":"Benevolent Synesthesia","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Benevolent%20Synesthesia","src":"AP #29 pg. 45","summary":"You transform the target’s brain, allowing them to see sounds, hear scents, and otherwise perceive sensory input using multiple sensory organs. Even unusual senses, such as a Shirren’s vibration sense, are affected."},"bestow_curse":{"name":"Bestow Curse","level":3,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Bestow%20Curse","src":"CRB pg. 341","summary":"You place a terrible curse on the target, stealing either its overall competency or its ability to think and act on its feet. Choose one of the following. The target takes a –4 penalty to ability checks, attack rolls, saving throws, and skill checks."},"bilocation":{"name":"Bilocation","level":6,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Bilocation","src":"AP #23 pg. 51","summary":"The spell creates an identical copy of you in an adjacent space, along with everything you wear and carry other than artifacts. (If you carry an artifact, you decide which body retains it.) You exist in two places at once until the spell ends."},"bioluminescent_lure":{"name":"Bioluminescent Lure","level":2,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Bioluminescent%20Lure","src":"AP #36 pg. 51","summary":"You cause a 30-foot-diameter sphere of water or other liquid to fill with bioluminescent plankton, increasing the light level from dark to dim or from dim to normal. For the spell’s duration, you can take a standard action to move this area up to 30 feet in any direction."},"biome_adaptation":{"name":"Biome Adaptation","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Biome%20Adaptation","src":"GM pg. 68","summary":"As the elves of yore, you attune the target to the surrounding environment or foresee their needs there, altering their coloration and movement to better match the biome (Core Rulebook 396) within which you cast this spell."},"biomechanical_symbiosis":{"name":"Biomechanical Symbiosis","level":2,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Biomechanical%20Symbiosis","src":"IS pg. 111","summary":"You energize the target’s natural healing. For 5 rounds, the target gains Fast Healing and electricity resistance based on the spell slot used to cast the spell."},"biotic_shroud":{"name":"Biotic Shroud","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Biotic%20Shroud","src":"AP #20 pg. 45","summary":"You conjure forth a mantle of organic, insectile nanites that encircle you. The density of the swarm provides you with partial concealment (20% miss chance) against ranged attacks."},"biotic_taclash":{"name":"Biotic Taclash","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Biotic%20Taclash","src":"AP #20 pg. 45","summary":"This spell functions as Biotic Taclash, Lesser, except that the created weapon is considered to be a magic weapon, deals 4d4 slashing damage, and functions as a level 10 item."},"biotic_taclash_lesser":{"name":"Biotic Taclash, Lesser","level":2,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Biotic%20Taclash%2C%20Lesser","src":"AP #20 pg. 45","summary":"You conjure a taclash made of organic, insectile nanites into your grasp. The created weapon functions as a standard taclash with the living weapon special property."},"blast_door":{"name":"Blast Door","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Blast%20Door","src":"COM pg. 133","summary":"You conjure a blast door up to 5 feet thick that blocks a hallway no more than 20 feet wide and 20 feet high. If the door would not completely block the targeted hallway, you can’t cast this spell."},"blessing_of_youth":{"name":"Blessing Of Youth","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Blessing%20Of%20Youth","src":"GM pg. 68","summary":"You rewind a living creature’s personal timeline to an earlier point in their life cycle, imbuing them with renewed vitality and restoring a number of Stamina Points. Blessing of youth ends the bleeding condition."},"body_double":{"name":"Body Double","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Body%20Double","src":"AP #35 pg. 54","summary":"Upon casting this spell, choose a primary target and a secondary target, both within range. If the primary target fails or forfeits its saving throw, its appearance, scent, sounds, and mannerisms change to match those of the secondary target."},"bolster_spell":{"name":"Bolster Spell","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Bolster%20Spell","src":"EN pg. 119","summary":"You lend some of your magical power to an ally as they cast a spell with a casting time of 1 round or less."},"borrow_corruption":{"name":"Borrow Corruption","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Borrow%20Corruption","src":"AP #12 pg. 53","summary":"You touch a willing creature with at least one manifestation from corruption and expend 2 Resolve Points. If you do so, you temporarily gain any stains and gifts that corruption grants to the target, and the target retains them."},"break_enchantment":{"name":"Break Enchantment","level":5,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Break%20Enchantment","src":"CRB pg. 341","summary":"This spell frees victims from curses, enchantments, and transmutations. Break enchantment can reverse even an instantaneous effect. For each such effect, you attempt a caster level check (1d20 + your caster level, maximum +15) against a DC equal to 11 + the caster level of the effect."},"broadcast_message":{"name":"Broadcast Message","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Broadcast%20Message","src":"GM pg. 69","summary":"You broadcast a short telepathic message of up to 25 words to all creatures in the area. The message repeats each round for the duration. A technomancer casting this spell also broadcasts the message to all computers or constructs with the technological subtype that are designed to receive messages."},"build_trust":{"name":"Build Trust","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Build%20Trust","src":"AP #25 pg. 45","summary":"You get a sense of the best way to interact with the target to encourage positive regard toward you. You gain a +2 circumstance bonus to Charisma checks, Charisma based skill checks, and Sense Motive checks you attempt when interacting with the target."},"burning_ash_cloud":{"name":"Burning Ash Cloud","level":3,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Burning%20Ash%20Cloud","src":"AP #18 pg. 53","summary":"You conjure forth a cloud of smoke and burning embers that billows out from the point you designate. The cloud obscures all sight, including darkvision beyond 5 feet."},"bypass_password":{"name":"Bypass Password","level":2,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Bypass%20Password","src":"GM pg. 69","summary":"Bypass password allows the caster to access a computer, control panel, or other similar digital device protected by a password. When you complete the casting of this spell, attempt a caster-level check (1d20 + your caster level) with a +10 bonus against the DC of the computer password."},"cairn_form":{"name":"Cairn Form","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Cairn%20Form","src":"GEM pg. 75","summary":"You transform your outer layer into solid rock, amplifying your offense and defense. You gain a special unarmed strike that deals lethal damage, doesn’t count as archaic, and threatens squares."},"call_cosmos":{"name":"Call Cosmos","level":5,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Call%20Cosmos","src":"CRB pg. 342","summary":"You evoke a vertical column of dangerous material from across the universe that rains down upon creatures in the area. This matter is made up of bits of burning stars and chunks of frozen comets, and it deals 4d6 fire damage and 3d6 cold damage to every creature in the area."},"calm_the_storm":{"name":"Calm The Storm","level":4,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Calm%20The%20Storm","src":"GM pg. 69","summary":"Developed by ikeshti brood-minders and congregants who moved beyond the threat of becoming a rivener, this spell is a celebration of the mental fortitude that one needs to resist one’s urges and to shrug off outside influence."},"capricious_cats":{"name":"Capricious Cats","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Capricious%20Cats","src":"PoC pg. 123","summary":"You conjure a pack of Tiny whimsical cats that scamper and perch within 30 feet of you wherever you move. These adorable felines are only semi-real and are immune to damage."},"carnivorous":{"name":"Carnivorous","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Carnivorous","src":"AP #2 pg. 51","summary":"Your mouth expands to twice its normal size,and fills with rows of razor-sharp teeth, giving you a bite attack."},"caustic_conversion":{"name":"Caustic Conversion","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Caustic%20Conversion","src":"CRB pg. 342","summary":"You fling magical nanites that convert water vapor around your target into deadly acid. Make a ranged attack roll against your target’s EAC. If you hit, the target takes 4d4 acid damage and it takes 5 additional acid damage at the end of its turn each round for the spell’s duration."},"caustic_fissure":{"name":"Caustic Fissure","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Caustic%20Fissure","src":"AP #48 pg. 51","summary":"You tear a thin fissure in reality, releasing a blaze of caustic energy. The fissure must be oriented on a horizontal surface that can fit its length, which depends on the level of the spell; the fissure runs through the center of the affected squares."},"cavitation_sphere":{"name":"Cavitation Sphere","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Cavitation%20Sphere","src":"AP #36 pg. 51","summary":"You cause a rapid change of pressure in liquid to form vapor-filled cavities, causing damaging localized shock waves. The target is surrounded by a series of quickly forming and dissipating rings that rotate around it."},"chain_surge":{"name":"Chain Surge","level":6,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Chain%20Surge","src":"CRB pg. 342","summary":"Choose a primary target as well as up to 10 secondary targets within 30 feet of the primary target. The primary target must be carrying or wielding some kind of equipment that uses electricity."},"change_of_seasons":{"name":"Change of Seasons","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Change%20of%20Seasons","src":"IS pg. 115","summary":"You accelerate time for the target, making them experience the concentrated effects of a Triaxian season."},"change_of_seasons_greater":{"name":"Change of Seasons, Greater","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Change%20of%20Seasons%2C%20Greater","src":"IS pg. 115","summary":"This spell functions like change of seasons except it causes vulnerability to fire or cold even if the target has resistance and reduces immunity to fire or cold resistance 5."},"channel_the_outer_sphere":{"name":"Channel the Outer Sphere","level":6,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Channel%20the%20Outer%20Sphere","src":"GM pg. 69","summary":"You weaken the border between one of the outer planes and the area, drawing concentrated planar essence down to the battlefield in beams of volatile energy. A beam is a vertical line, 5 feet wide, from the top of the spell’s area to the bottom, and it deals 4d8 damage to each creature in the beam."},"charm_monster":{"name":"Charm Monster","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Charm%20Monster","src":"CRB pg. 342","summary":"This spell functions like Charm Person, except the effect is not restricted by creature type. Charm Person This charm makes a humanoid creature regard you as its trusted friend and ally (treat the target’s attitude as friendly)."},"charm_person":{"name":"Charm Person","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Charm%20Person","src":"CRB pg. 342","summary":"This charm makes a humanoid creature regard you as its trusted friend and ally (treat the target’s attitude as friendly). If the creature is currently being threatened or attacked by you or your allies, however, it receives a +5 bonus to its saving throw."},"charming_veneer":{"name":"Charming Veneer","level":0,"school":"ill","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Charming%20Veneer","src":"COM pg. 133","summary":"You pull gossamer threads from other, more genteel realities and wrap the target in them, smoothing the edges of their personality and accentuating their charms. The target gains a +1 circumstance bonus to Charisma checks and Charisma-based skill checks."},"cheat_time":{"name":"Cheat Time","level":6,"school":"abj","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Cheat%20Time","src":"GM pg. 70","summary":"You unfetter yourself in time, rapidly performing a variety of actions in the blink of an eye. You can perform up to six actions from the following options, in a combination and order of your choice, though some actions end the spell immediately."},"chromatic_safeguard":{"name":"Chromatic Safeguard","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Chromatic%20Safeguard","src":"EN pg. 120","summary":"You create a faint, multicolored aurora around the target, providing resistance against energy attacks. The aurora consists of 3 colorful wisps, plus one additional wisp for every 4 caster levels you have, and each wisp protects against a specific damage type determined by its color."},"chromatic_safeguard_greater":{"name":"Chromatic Safeguard, Greater","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Chromatic%20Safeguard%2C%20Greater","src":"EN pg. 120","summary":"This spell functions as Chromatic Safeguard, but each wisp reduces the damage dealt by 1d10+10."},"chronal_assault":{"name":"Chronal Assault","level":6,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Chronal%20Assault","src":"EN pg. 120","summary":"You appear to teleport across the battlefield in short jumps, make attacks, and then teleport again. In truth, you repeatedly pause time as you move from place to place, unpausing time just long enough to make attacks."},"chrono_leap":{"name":"Chrono Leap","level":5,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Chrono%20Leap","src":"GM pg. 70","summary":"You rocket the target forward through time, sending them careening across the battlefield. You move the target up to 60 feet in a straight line. This movement doesn’t provoke attacks of opportunity."},"chronosphere":{"name":"Chronosphere","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Chronosphere","src":"EN pg. 120","summary":"You create and hurl a sphere of temporal distortion at a foe, disrupting their body and slowing their movements. Make a ranged attack roll against the target’s EAC, but you can add your key ability score modifier instead of your Dexterity modifier to the attack roll if it is higher."},"churn_fluid":{"name":"Churn Fluid","level":0,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Churn%20Fluid","src":"COM pg. 134","summary":"You merge a tiny corner of parallel realities with this one, subtly or dramatically shifting the chemical composition of a fluid. You can target any type of fluid, and you need not know its current composition."},"clairaudienceclairvoyance":{"name":"Clairaudience/Clairvoyance","level":3,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Clairaudience/Clairvoyance","src":"CRB pg. 342","summary":"You create an invisible magical sensor at a specific location that enables you to hear or see (your choice) almost as if you were there."},"climate_adaptation":{"name":"Climate Adaptation","level":0,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Climate%20Adaptation","src":"GM pg. 70","summary":"You tweak a creature’s genetic code, altering its environmental adaptations to better suit the surrounding climate. For the duration, the target reduces the severity of dangerous temperatures by one step. For example, cold is reduced to comfortable, while extreme heat is reduced to severe heat."},"command":{"name":"Command","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Command","src":"CRB pg. 343","summary":"You give the target one of the following commands, which it obeys to the best of its ability at its earliest opportunity. If the target can’t carry out your command on its next turn, the spell automatically fails."},"command_greater":{"name":"Command, Greater","level":5,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Command%2C%20Greater","src":"CRB pg. 343","summary":"This spell functions like Command, except you can affect up to one creature per level and the targets continue the specified activity beyond 1 round. At the start of each commanded creature’s action after the first, it can attempt another Will saving throw to break free from the spell."},"command_icon":{"name":"Command Icon","level":1,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Command%20Icon","src":"GM pg. 70","summary":"Hobgoblins created this spell to signify rallying points and provide commanders with better ability to organize troops. The target creature seems more imposing, granting the creature a +2 morale bonus to Charisma-based checks made to motivate troops and all Intimidate checks."},"command_undead":{"name":"Command Undead","level":2,"school":"nec","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Command%20Undead","src":"CRB pg. 343","summary":"This spell allows you a degree of control over an undead creature. If the target is intelligent, it perceives your words and actions favorably (treat its attitude as friendly). It will not attack you while the spell lasts."},"communal_bond":{"name":"Communal Bond","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Communal%20Bond","src":"GM pg. 71","summary":"This spell arises from ghorans’ tradition of imbuing their group projects and celebrations of togetherness with magic. Targets gain a +1 morale bonus to saving throws against fear effects while they’re observing at least one other target of the same casting of this spell."},"commune_with_nature":{"name":"Commune with Nature","level":5,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Commune%20with%20Nature","src":"CRB pg. 344","summary":"You become one with nature, attaining knowledge of the surrounding territory."},"commune_with_planet":{"name":"Commune With Planet","level":5,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Commune%20With%20Planet","src":"COM pg. 134","summary":"You form a connection with a planet you are on or in orbit of, instantly learning up to three facts from among the following: major settlements, basic attributes (location in the galaxy, diameter and mass, gravity, atmosphere, and day and year length), ecological state (such as untamed…"},"companion_bond":{"name":"Companion Bond","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Companion%20Bond","src":"GM pg. 71","summary":"As the lashuntas who created this spell, you forge a telepathic link with a pet, mount, or other creature, provided the creature has an Intelligence modifier and that modifier is –2 or lower, and the creature is of the aberration, animal, dragon, magical beast, or plant type."},"compounding_failure":{"name":"Compounding Failure","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Compounding%20Failure","src":"EN pg. 120","summary":"You fill the target’s mind with self-doubt, pernicious ruminations, and crushing inadequacy. The target gains the Shaken condition for the spell’s duration, though this condition is not a fear effect and cannot be removed by effects that specifically negate fear effects."},"comprehend_customs":{"name":"Comprehend Customs","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Comprehend%20Customs","src":"COM pg. 134","summary":"This spell grants you a +2 insight bonus to Culture checks you attempt during the duration. The insight you gain might help you greet someone properly, know whether physical contact (a handshake, for example) is appropriate, or how to eat without making a mess or insulting your host."},"comprehend_languages":{"name":"Comprehend Languages","level":1,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Comprehend%20Languages","src":"CRB pg. 344","summary":"You can understand the spoken or signed words of creatures or read otherwise incomprehensible written or tactile messages. The ability to read does not necessarily impart insight into the material, merely its literal meaning."},"conduit_of_destruction":{"name":"Conduit of Destruction","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Conduit%20of%20Destruction","src":"EN pg. 121","summary":"Rather than shaping your magical power into a specific spell, you exude raw magic as a destructive aura."},"confusion":{"name":"Confusion","level":4,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Confusion","src":"CRB pg. 344","summary":"This spell causes Confusion in all creatures in the area, making them unable to determine their actions. Any Confused creature that is attacked automatically attacks or attempts to attack its attackers on its next turn, as long as it is still Confused at the start of its next turn."},"confusion_lesser":{"name":"Confusion, Lesser","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Confusion%2C%20Lesser","src":"CRB pg. 344","summary":"This spell causes a single creature to become Confused (as per the Confusion spell) for 1 round."},"conjure_grenade":{"name":"Conjure Grenade","level":0,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Conjure%20Grenade","src":"PoC pg. 83","summary":"You rapidly conjure and assemble the components to make a grenade, which you throw as part of the action used to cast this spell, requiring an attack roll to hit the intersection as normal. The grenade has a 20-foot range increment, deals 1d4 piercing damage, and has the explode (5 feet) property."},"contact_other_plane":{"name":"Contact Other Plane","level":5,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Contact%20Other%20Plane","src":"CRB pg. 344","summary":"You send your mind to another plane of existence (an Elemental Plane or some plane further removed) in order to receive advice and information from powers there. The powers reply in a language you understand, but they resent such contact and give only brief answers to your questions."},"control_atmosphere":{"name":"Control Atmosphere","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Control%20Atmosphere","src":"PW pg. 204","summary":"You can alter the atmosphere within the spell’s area to cause it to become more like the atmosphere of another planet. You can alter one aspect of the atmosphere—its corrosiveness, density, or toxicity. The possible effects of each of these changes are detailed below."},"control_gravity":{"name":"Control Gravity","level":6,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Control%20Gravity","src":"CRB pg. 345","summary":"You can control gravity in an area, causing it to reverse, become zero-g, or become extremely strong."},"control_machines":{"name":"Control Machines","level":5,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Control%20Machines","src":"CRB pg. 345","summary":"You wrest control of the target constructs and command them telepathically. You can issue commands to any number of controlled constructs on your turn, beginning when you cast this spell, as part of the concentration required to sustain its duration (a standard action)."},"control_undead":{"name":"Control Undead","level":6,"school":"nec","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Control%20Undead","src":"CRB pg. 345","summary":"This spell enables you to control undead creatures for a short period of time. You command them by voice and they understand you, no matter what language you speak. No matter what, the controlled undead do not attack you. At the end of the spell, the targets revert to their normal behavior."},"control_winds":{"name":"Control Winds","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Control%20Winds","src":"GEM pg. 114","summary":"You alter the movement of air in an area around you. Wind created by this spell imposes a penalty to Perception checks equal to the penalty the wind imposes on non-energy ranged weapon attacks (see Table 11–6: Wind Effects on page 400 of the Core Rulebook)."},"corrosive_haze":{"name":"Corrosive Haze","level":4,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Corrosive%20Haze","src":"CRB pg. 346","summary":"A 5-foot cloud of acid-resistant nanites continually converts nearby water vapor into deadly acid. You can create the cloud in the same square as a creature and move it up to 30 feet in any direction as a move action on your turn."},"cosmic_eddy":{"name":"Cosmic Eddy","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Cosmic%20Eddy","src":"CRB pg. 346","summary":"You pull dormant mystical energy from the land and objects around you and use it to create a swirling eddy that batters your foes and can hinder their movement. The eddy deals 4d6 bludgeoning damage to each creature in the area."},"create_ammunition":{"name":"Create Ammunition","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Create%20Ammunition","src":"COM pg. 134","summary":"You create a specific type of ammunition, such as arrows or a battery, and conjure it in hand or a place within range."},"creation":{"name":"Creation","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Creation","src":"CRB pg. 347","summary":"You create a nonmagical, nontechnological, unattended object of nonliving matter. The volume of the item created can’t exceed 1 cubic foot (or 1 bulk) per caster level. You must succeed at an appropriate Engineering or Profession check to make a complex item, and you can’t create a consumable item."},"crush_skull":{"name":"Crush Skull","level":5,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Crush%20Skull","src":"CRB pg. 347","summary":"You manipulate the energy that swirls around the target’s head, pulling it inward and potentially crushing its skull."},"crystal_eruption":{"name":"Crystal Eruption","level":2,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Crystal%20Eruption","src":"IS pg. 123","summary":"You force unstable magic into the ground, causing jagged crystals to erupt in the area. Creatures in the area and in contact with the ground when the spell first takes effect take 2d8 piercing damage."},"crystal_mine":{"name":"Crystal Mine","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Crystal%20Mine","src":"IS pg. 123","summary":"You create three electrified crystal proximity mines under the ground within range. Each mine must be within 30 feet of at least one of the other mines. Each mine occupies one 5-foot square and remains for the duration or until triggered."},"daegoxian_spore_cloud":{"name":"Daegoxian Spore Cloud","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Daegoxian%20Spore%20Cloud","src":"NS pg. 155","summary":"You summon a concentrated cloud of Daegoxian spores, which renders living creatures docile and agreeable. Any creature that enters the cloud or begins its turn within the cloud must succeed at a Will save or be Fascinated for 1d4 rounds."},"dampen_spell":{"name":"Dampen Spell","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dampen%20Spell","src":"GM pg. 71","summary":"You siphon magical energy from a spell, casting dampen spell as a reaction when you observe the triggering spell being cast within range. This spell has no effect on magic items but can affect spells they cast."},"dampening_field":{"name":"Dampening Field","level":2,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dampening%20Field","src":"NS pg. 155","summary":"The target becomes encased in a field that dampens sounds and vibrations."},"dancing_lights":{"name":"Dancing Lights","level":0,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dancing%20Lights","src":"CRB pg. 347","summary":"You create up to four lights that resemble small headlights or flashlights. The dancing lights must stay within a 10-foot-radius area in relation to each other but otherwise move as you desire: forward or back, up or down, straight or turning corners, or the like."},"darkvision":{"name":"Darkvision","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Darkvision","src":"CRB pg. 347","summary":"The target gains the ability to see 60 feet even in total darkness. Darkvision is black and white only but otherwise like normal sight."},"data_dump":{"name":"Data Dump","level":4,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Data%20Dump","src":"AP #32 pg. 53","summary":"When you cast this spell, attempt a Computers or Mysticism check; you gain access to the data in the computer or any of its secure data modules with a DC to hack equal to or less than the result of your check."},"day's_weariness":{"name":"Day's Weariness","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Day%27s%20Weariness","src":"GM pg. 72","summary":"You launch an opponent’s mind forward in time, forcing them to experience a day’s events in a moment. The target takes 4d8 damage and becomes Fatigued for the duration, or they become Exhausted for the duration if already fatigued."},"daze":{"name":"Daze","level":0,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Daze","src":"CRB pg. 347","summary":"This spell short-circuits the mind of a humanoid creature with a CR of 3 or lower so that it is Dazed (unable to take actions, but taking no penalty to AC). Humanoids of CR 4 or higher are not affected. After a creature has been Dazed by this spell, it is immune to it for 1 minute."},"daze_monster":{"name":"Daze Monster","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Daze%20Monster","src":"CRB pg. 347","summary":"This spell functions like Daze, but it can affect any one living creature of any type up to CR 5. Creatures of CR 6 or higher are not affected."},"dazzling_flares":{"name":"Dazzling Flares","level":0,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dazzling%20Flares","src":"COM pg. 134","summary":"You evoke fist-sized pockets of existence from multiple realities, creating chemical reactions that result in up to a dozen flares. These flares appear at once, and they do so within a 10-foot-radius spread."},"death's_door":{"name":"Death's Door","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Death%27s%20Door","src":"GM pg. 72","summary":"You accelerate a living opponent’s personal timeline to the end of their natural life cycle, unleashing the ravages of time in a devastating surge. The target can attempt a Fortitude saving throw to halve the damage and ignore the ability damage dealt by this spell."},"death_affinity":{"name":"Death Affinity","level":3,"school":"nec","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Death%20Affinity","src":"NS pg. 155","summary":"You infuse the target with necromantic energy, physically altering their form into an amalgam of life and undeath."},"death_ward":{"name":"Death Ward","level":4,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Death%20Ward","src":"CRB pg. 348","summary":"The target gains a +4 morale bonus to saving throws against all spells and effects with the death descriptor. The target can attempt a save to negate such effects even if one is not normally allowed. The target can’t gain negative levels and is immune to any negative energy effects."},"deceptive_afterimages":{"name":"Deceptive Afterimages","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Deceptive%20Afterimages","src":"EN pg. 122","summary":"You dilate time and space around a creature, creating a set of confusing afterimages that make it difficult to pinpoint their exact movements."},"deep_slumber":{"name":"Deep Slumber","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Deep%20Slumber","src":"CRB pg. 348","summary":"This spell causes living creatures in the area to fall into a magical sleep, gaining the Asleep condition (except normal noise doesn’t wake up the sleeping creatures). Creatures with the lowest CR are affected first."},"defrex_hardiness":{"name":"Defrex Hardiness","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Defrex%20Hardiness","src":"NS pg. 155","summary":"The target becomes infused with the resilience of a defrex and sprouts bristling spines. It gains DR/— equal to half your caster level, and any creature adjacent to the target that hits it with a melee attack takes piercing damage equal to half your caster level."},"degrade_programming":{"name":"Degrade Programming","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Degrade%20Programming","src":"EN pg. 122","summary":"You rapidly age a computer system, module, or construct, introducing errors, overloading systems, and degrading its software. If you cast this spell on a computer, the computer becomes unreliable and difficult to use."},"delay_countermeasures":{"name":"Delay Countermeasures","level":2,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Delay%20Countermeasures","src":"COM pg. 134","summary":"Countermeasures on the target computer are suppressed. If you trigger any suppressed countermeasure, you are still alerted that you have done so, but it activates only after the spell ends."},"deprive_knowledge":{"name":"Deprive Knowledge","level":2,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Deprive%20Knowledge","src":"AP #32 pg. 53","summary":"You strip the target creature of key knowledge. Choose one skill; for the duration of the spell, the target takes a –4 penalty to the chosen skill. If you choose Culture, this also strips the target of up to 4 languages, determined randomly."},"destruction_protocol":{"name":"Destruction Protocol","level":4,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Destruction%20Protocol","src":"CRB pg. 348","summary":"Waves of inciting programming ebb from your touch, reprogramming a construct to have murderous intentions toward your enemies. This spell must target a construct that is not already programmed or tasked with harming you. The target construct must have a CR lower than or equal to your level."},"destructive_rebuke":{"name":"Destructive Rebuke","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Destructive%20Rebuke","src":"DC pg. 135","summary":"You convert your pain and emotional distress into a sharp, forceful reverberation that fractures another creature’s body. The target can attempt a Fortitude saving throw to halve the damage dealt by the spell and negate any additional effects."},"detect_affliction":{"name":"Detect Affliction","level":0,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Detect%20Affliction","src":"CRB pg. 348","summary":"You determine whether a creature or object has been poisoned, is diseased, is cursed, or is suffering a similar affliction."},"detect_augmentation":{"name":"Detect Augmentation","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Detect%20Augmentation","src":"AR pg. 148","summary":"You detect the presence of augmentations installed within creatures you can see within the area, which appear to you as glowing outlines around the systems in which the augmentations are installed."},"detect_magic":{"name":"Detect Magic","level":0,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Detect%20Magic","src":"CRB pg. 348","summary":"You detect all magic spells, effects, items, and objects (including those on or affecting creatures you can see), as well as hybrid items, in the area. You can’t detect magical traps in this way, as they are created with additional magic that wards them from this common spell."},"detect_radiation":{"name":"Detect Radiation","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Detect%20Radiation","src":"CRB pg. 348","summary":"You detect radiation in the surrounding area, and you can determine the specific intensity of the radiation of one area or object within the spell’s area each round without taking an action (see Radiation on page 403 for more details)."},"detect_tech":{"name":"Detect Tech","level":1,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Detect%20Tech","src":"CRB pg. 349","summary":"You detect all technological items (even hybrid items) with charges or that replenish charges in the area, including batteries, power cells, and generators (as well as such items that are on creatures you can see, even if the creatures have hidden those items on themselves)."},"detect_thoughts":{"name":"Detect Thoughts","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Detect%20Thoughts","src":"CRB pg. 349","summary":"You detect the surface thoughts of intelligent creatures around you. The amount of information revealed depends on how long you study a particular area or target."},"digital_doorway":{"name":"Digital Doorway","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Digital%20Doorway","src":"PW pg. 205","summary":"You gain the ability to step into a piece of electronic equipment currently connected to a communication or information network (such as a comm unit or a computer connected to an infosphere), converting yourself into digital information and traveling along the network."},"digital_shield":{"name":"Digital Shield","level":2,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Digital%20Shield","src":"AA4 pg. 37","summary":"When you take damage from an effect, you can create a defensive conduit between yourself and one technological object, non-archaic armor, or non‑archaic weapon you’re carrying or wearing that’s 3 Bulk or less."},"dimension_door":{"name":"Dimension Door","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dimension%20Door","src":"CRB pg. 349","summary":"You instantly transfer yourself from your current location to any other spot within range. You always arrive at exactly the spot desired—whether by simply visualizing the area or by stating its direction. You can bring along objects as long as their weight doesn’t exceed your maximum load."},"dimensional_anchor":{"name":"Dimensional Anchor","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dimensional%20Anchor","src":"AA3 pg. 53, AP #16 pg. 55","summary":"You fire a ray at the target, making a ranged attack against its EAC. On a hit, the target is covered in a shimmering field that prevents planar travel."},"dimensional_crash":{"name":"Dimensional Crash","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dimensional%20Crash","src":"DC pg. 139","summary":"You instantly transfer yourself from your current location to a spot within range that’s occupied by another creature, otherwise functioning as per {Dimension Door. You take 1d6 bludgeoning damage, and the other creature takes 3d6 bludgeoning damage (Reflex half)."},"directed_denial_of_strength_attack":{"name":"Directed Denial Of Strength Attack","level":2,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Directed%20Denial%20Of%20Strength%20Attack","src":"PW pg. 205","summary":"You flood targets’ minds with a magical effect similar to a computer virus that duplicates every sensation of lifting, carrying, and being burdened. Targets become Encumbered, or they become Overburdened if already Encumbered."},"discern_lies":{"name":"Discern Lies","level":4,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Discern%20Lies","src":"CRB pg. 349","summary":"Each round, you concentrate on one target within range. You know if the target deliberately and knowingly speaks a lie by discerning disturbances in its aura caused by lying. The spell does not reveal the truth or uncover unintentional inaccuracies, and it doesn’t necessarily reveal evasions."},"discharge":{"name":"Discharge","level":3,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Discharge","src":"CRB pg. 350","summary":"You can dissipate the charges from one technological object, temporarily depower one electrically powered technological object that does not use charges, or severely hinder a construct with the technological subtype."},"discharge_greater":{"name":"Discharge, Greater","level":6,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Discharge%2C%20Greater","src":"CRB pg. 350","summary":"This spell functions as Discharge, except it can discharge multiple technological objects. You can use it in one of two ways: an area discharge or a targeted discharge. Area Discharge: When used in this way, the spell affects everything within a 20-foot-radius burst."},"disguise_self":{"name":"Disguise Self","level":1,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Disguise%20Self","src":"CRB pg. 350","summary":"You make yourself—and any clothing, armor, weapons, and equipment on you—look different. You can seem up to 1 foot shorter or taller, thin, fat, or in between. You can’t change your creature type (although you can appear as another subtype). Otherwise, the extent of the apparent change is up to you."},"disintegrate":{"name":"Disintegrate","level":6,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Disintegrate","src":"CRB pg. 350","summary":"Immense power shoots from your finger, with the potential to disintegrate a target where it stands. When you cast this spell, a thin, green ray springs from your pointing finger."},"dismissal":{"name":"Dismissal","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dismissal","src":"CRB pg. 350","summary":"The spell instantly forces one or more extraplanar creatures off your current plane, whisking them away instantly—usually to the creature’s home plane, but there is a 20% chance of sending the target to a random plane other than its own."},"dispel_magic":{"name":"Dispel Magic","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dispel%20Magic","src":"CRB pg. 351","summary":"You can use dispel magic to end one ongoing spell that has been cast on a creature or object, to temporarily suppress the magical abilities of a magic item, or to counter another spellcaster’s spell. A dispelled spell ends as if its duration had expired."},"dispel_magic_greater":{"name":"Dispel Magic, Greater","level":5,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dispel%20Magic%2C%20Greater","src":"CRB pg. 352","summary":"This spell functions like Dispel Magic, except it can end more than one spell on a target and it can be used to target multiple creatures. You choose to use greater dispel magic in one of three ways: a targeted dispel, an area dispel, or a counter."},"displace_memory":{"name":"Displace Memory","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Displace%20Memory","src":"COM pg. 134","summary":"You move one of your memories into the target object. You can select up to 5 minutes of continuous memory, or you can select every memory associated with one person, place, or object you name when you cast this spell."},"displacement":{"name":"Displacement","level":3,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Displacement","src":"CRB pg. 352","summary":"The target of this spell appears to be about 2 feet away from its true location. The creature benefits from a 50% miss chance as if it had total concealment. Unlike actual total concealment, displacement doesn’t prevent enemies from targeting the creature normally."},"dissonance_strike":{"name":"Dissonance Strike","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dissonance%20Strike","src":"GM pg. 72","summary":"You harness the vibrations in your body and a body you strike. Attempt a melee attack against the target’s EAC. If your attack hits, the target takes 4d4 sonic damage (critical deafen; DC equals your spell save DC) and can’t take reactions for 1 round."},"distant_speech":{"name":"Distant Speech","level":0,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Distant%20Speech","src":"GM pg. 72","summary":"Your speech is audible for up to half a mile outdoors or 1,000 feet indoors. The volume of your voice doesn’t change, so intervening obstacles and louder noises can still drown it out."},"distract":{"name":"Distract","level":2,"school":"ill","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Distract","src":"GM pg. 72","summary":"You distract a creature with a sudden illusory noise or image. This functions as a feint action except that you can use your Mysticism skill in place of Bluff, and you can apply the benefits of the Improved Feint and Greater Feint feats if you have them."},"divination":{"name":"Divination","level":4,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Divination","src":"CRB pg. 352","summary":"Similar to augury but more powerful, a divination spell can provide you with a useful piece of advice in reply to a question concerning a specific goal, event, or activity that is to occur within 1 week. Casting this spell requires you to expend 1 Resolve Point."},"divine_aspect":{"name":"Divine Aspect","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Divine%20Aspect","src":"COM pg. 135","summary":"You take on a terrifying aura that evokes a specific god, an aspect of divinity, a mystic concept, or another mighty force. For the duration, you are immune to fear effects, and you gain Frightful Presence as a supernatural ability with a range of 30 feet and a Will save DC equal to the spell’s DC."},"dominate_person":{"name":"Dominate Person","level":5,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dominate%20Person","src":"CRB pg. 352","summary":"You fire a bright purple ray at your target, making a ranged attack against your target’s EAC, but you can add your key ability score bonus to this attack instead of your Dexterity modifier if it is higher."},"dream_of_home":{"name":"Dream Of Home","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Dream%20Of%20Home","src":"GM pg. 73","summary":"Drawing on the magic of the kasathan Pillar of the Homeworld or similar homey memories, you overwhelm the target with pleasant visions and thoughts of their home, whatever that means to them. If the target fails the saving throw, they become Fascinated for the duration."},"drift_messenger":{"name":"Drift Messenger","level":5,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Drift%20Messenger","src":"DC pg. 93","summary":"You briefly summon an Iridia, a spectra native to the Drift (Alien Archive 3 102), to deliver a message for you."},"drift_prediction":{"name":"Drift Prediction","level":4,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Drift%20Prediction","src":"DC pg. 122","summary":"You glimpse a narrow range of possibilities related to a starship’s next Drift journey initiated within the next 24 hours. When you cast this spell, choose one of the following distances: travel in-system, travel to Absalom station, travel to Near Space, or travel to the Vast."},"duplicate_data":{"name":"Duplicate Data","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Duplicate%20Data","src":"GM pg. 73","summary":"You instantly copy all data stored on a single computer or secure data module onto another device in your possession with adequate storage capacity. If the data is protected by countermeasures, these countermeasures are copied along with the data."},"eclipse_touch":{"name":"Eclipse Touch","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Eclipse%20Touch","src":"AP #30 pg. 52","summary":"In the darkened halls of the Eclipse Academy, only the most ruthless students survive."},"ectoplasmic_barrage":{"name":"Ectoplasmic Barrage","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ectoplasmic%20Barrage","src":"AP #23 pg. 51","summary":"You fling psychic material, called ectoplasm, at the target, making a ranged attack against its KAC and dealing bludgeoning damage. Each projectile in the barrage has the Knockdown critical hit effect."},"ectoplasmic_eruption":{"name":"Ectoplasmic Eruption","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ectoplasmic%20Eruption","src":"AP #23 pg. 52","summary":"Swirling psychic matter, known as ectoplasm, erupts from a point you choose. Those in the area take 6d6 bludgeoning damage. Those who fail the Reflex saving throw are Entangled for the spell’s duration."},"ectoplasmic_snare":{"name":"Ectoplasmic Snare","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ectoplasmic%20Snare","src":"AP #23 pg. 52","summary":"You launch a writhing tendril of ectoplasm to snare a creature. Make a ranged attack roll against your target’s EAC. If you hit, the target can attempt a Reflex save. On a successful save, the target is Entangled for the duration."},"ego_whip":{"name":"Ego Whip","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ego%20Whip","src":"AP #23 pg. 52","summary":"You overwhelm your opponent’s ego, diminishing its sense of self, hope, and confidence. The target takes a –2 penalty to Intelligence-, Wisdom-, and Charisma-based checks; its spell save DCs; and its Will saving throws. In addition, the target is Staggered for the duration."},"electric_light_show":{"name":"Electric Light Show","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Electric%20Light%20Show","src":"AP #30 pg. 53","summary":"A favorite among SENOT students, this spell lets you create a charming electrical light show that can mimic fireworks, skywrite a message or logo, or depict anything—from birds and butterflies to a colorful dragon or starship."},"electroplating":{"name":"Electroplating","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Electroplating","src":"AR pg. 157","summary":"When you cast this spell, you create a temporary quantity of silver in a cloud of charged nanoparticles, which you then direct to coat nearby melee or projectile weapons. The target weapons must deal bludgeoning, piercing, or slashing damage or the spell has no effect."},"elemental_convergence":{"name":"Elemental Convergence","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Elemental%20Convergence","src":"GM pg. 73","summary":"You tap into the power of two elemental planes, mix their energy together, and then release it around you in a powerful explosion, dealing 8d8 damage. Select two of the following damage types when you cast this spell: acid, cold, electricity, fire."},"emberstep":{"name":"Emberstep","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Emberstep","src":"AP #18 pg. 53","summary":"For the duration of this spell, you leave behind a trail of faintly burning embers in any square that you move through. These embers have no effect except for providing dim light in those squares. The embers disappear at the start of your next turn."},"embrace_of_the_void":{"name":"Embrace of the Void","level":1,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Embrace%20of%20the%20Void","src":"AP #45 pg. 51","summary":"You wrap the target in the cold of the Negative Energy Plane, numbing its body. The target might lose feeling in its extremities or even be temporarily frozen in place. The target takes half damage on a successful save."},"empathic_communication":{"name":"Empathic Communication","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Empathic%20Communication","src":"GM pg. 73","summary":"With this spell, common among shirren mystics, you transmit your emotions into the surrounding area, allowing you to empathically communicate with others."},"empathic_support":{"name":"Empathic Support","level":2,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Empathic%20Support","src":"GM pg. 73","summary":"When the target uses aid another, covering fire, or harrying fire, and succeeds at their attack roll or skill check, they can forgo granting their ally the usual benefit of that action to instead grant the following benefits, determined by the action they used."},"enduring_stylus":{"name":"Enduring Stylus","level":0,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Enduring%20Stylus","src":"AP #42 pg. 42","summary":"You trace a symbol or phrase upon a nonmagical object or solid surface with your touch, which becomes permanently imprinted on the object’s surface. The imprint doesn’t harm the object or surface in any way and can be no larger than 6 inches square."},"enduring_worlds":{"name":"Enduring Worlds","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Enduring%20Worlds","src":"COM pg. 135","summary":"You cast this spell during the duration of an ongoing environmental effect you’ve created using your Infinite Worlds (Su) class feature, refining your grasp on the overlapping realities around you. When you do so, this spell extends those effects for its duration."},"energy_ray":{"name":"Energy Ray","level":0,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Energy%20Ray","src":"CRB pg. 353","summary":"When you cast this spell, choose acid, cold, electricity, or fire; the spell gains that descriptor. You fire a ray at the target, and you must make a ranged attack against its EAC. On a hit, the ray deals 1d3 damage of the chosen energy type."},"enervation":{"name":"Enervation","level":4,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Enervation","src":"CRB pg. 353","summary":"You shoot a black ray at a target, making a ranged attack against the target’s EAC. If you hit, the target gains 2 temporary negative levels. Negative levels stack. If the target survives, it recovers from negative levels after a number of hours equal to your caster level (maximum 15 hours)."},"enshrining_refuge":{"name":"Enshrining Refuge","level":6,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Enshrining%20Refuge","src":"CRB pg. 353","summary":"All creatures within a 40-foot radius of the spell’s point of origin are protected from violence. Any opponent attempting to directly attack a warded creature, even with a targeted spell, must attempt a Will saving throw."},"entropic_grasp":{"name":"Entropic Grasp","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Entropic%20Grasp","src":"CRB pg. 353","summary":"Any unattended, manufactured (built from component parts, including metal, wood, plastic, glass, and so on) item you touch crumbles into dust, rust, and decay. If the item is so large that it can’t fit within a 3-foot radius, a 3-foot-radius volume of the material is destroyed."},"erase":{"name":"Erase","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Erase","src":"CRB pg. 353","summary":"Erase removes writings of either magical or mundane nature from any written storage, including paper, computers, or similar devices. You remove up to 1,500 words worth of text (for computer files, this could be a 1,500-word data file or 1,500 words of computer code)."},"erase_existence":{"name":"Erase Existence","level":6,"school":"nec","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Erase%20Existence","src":"EN pg. 122","summary":"You rapidly rewind time for all creatures in the area to a moment before they were born, potentially erasing them from existence completely. Each creature in the area takes 12d8 slashing damage (Fortitude half)."},"ethereal_jaunt":{"name":"Ethereal Jaunt","level":6,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ethereal%20Jaunt","src":"CRB pg. 354","summary":"You become ethereal, along with your equipment. For the duration of the spell, you are on the Ethereal Plane, which overlaps the Material Plane. When the spell expires, you return to material existence."},"etheric_shards":{"name":"Etheric Shards","level":3,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Etheric%20Shards","src":"AP #23 pg. 52","summary":"You harden ethereal matter into interplanar blades that are invisible to those who cannot see into the Ethereal Plane."},"explosive_blast":{"name":"Explosive Blast","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Explosive%20Blast","src":"CRB pg. 354","summary":"You magically transform a used battery into a powerful explosive device, propelling it in a straight line to a grid intersection within range, at which point it detonates, dealing 9d6 fire damage to all creatures and objects in the area."},"extra_sense":{"name":"Extra Sense","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Extra%20Sense","src":"GEM pg. 114","summary":"You magically amplify or add to a target’s senses. 1st: When you cast extra sense as a 1st-level spell, the target gains blindsense (vibration) out to a range of 30 feet. The blindsense can be based on scent or sound rather than vibration."},"fabricate_scrap":{"name":"Fabricate Scrap","level":0,"school":"uni","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fabricate%20Scrap","src":"SA:JD pg. 58, #1 PW pg. 205","summary":"You turn 1 bulk of inert matter, such as debris, dust, rocks, or other unattended 0-level items, into 1 bulk of junked electronic equipment suitable for targeting with spells such as Battle Junkbot, Handy Junkbot, Healing Junkbot, Junk Armor, or Junksword."},"fantastical_transformation":{"name":"Fantastical Transformation","level":5,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fantastical%20Transformation","src":"EN pg. 122","summary":"In a dazzling display of light, color, fantastical effects, and music, you adopt a flashy battle persona that transforms the appearance of your clothing, equipment, hair, and other features as you desire. For the duration of the spell, you exude majesty in a 30-foot radius."},"fatigue":{"name":"Fatigue","level":0,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fatigue","src":"CRB pg. 354","summary":"You make a melee attack against a single target’s EAC, adding your key ability score modifier to the attack roll instead of your Strength modifier if it is higher. The target must succeed at a Fortitude save or be fatigued for the spell’s duration."},"fear":{"name":"Fear","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fear","src":"CRB pg. 354","summary":"With a single mental nudge, you can unlock one or more targets’ deepest nightmares. A target that succeeds at its Will saving throw against this spell is Shaken for 1 round."},"fearsome_reputation":{"name":"Fearsome Reputation","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fearsome%20Reputation","src":"EN pg. 123","summary":"You wrap the target in a fearsome aura. When the target fails an Intimidate check or fails a saving throw against a fear effect, they can dismiss this spell as a reaction. When they do so, they can reroll the Intimidate check or saving throw and use the better result."},"feeblemind":{"name":"Feeblemind","level":5,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Feeblemind","src":"CRB pg. 354","summary":"You fire a scintillating ray at your target, making a ranged attack against your target’s EAC, but you can add your key ability score bonus to this attack instead of your Dexterity modifier if it is higher."},"fey_pranksters":{"name":"Fey Pranksters","level":3,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fey%20Pranksters","src":"AP #30 pg. 53","summary":"This spell was created and used to win a Nerundel Halls prank challenge a few years ago. You summon a 10-foot-by-10-foot swarm of mischievous fey creatures armed with various tiny weapons who fly around chaotically."},"fist_of_damoritosh":{"name":"Fist Of Damoritosh","level":6,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fist%20Of%20Damoritosh","src":"GM pg. 4","summary":"You form a fist of divine energy and thrust it outward, damagingand potentially knocking down your enemies. You deal 12d8 damage with the force descriptor to each creature in the area. A creature that fails its Reflex save is additionally knocked prone."},"flash_boil":{"name":"Flash Boil","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Flash%20Boil","src":"AP #36 pg. 51","summary":"You cause water in the spell’s area to instantly boil, dealing 7d8 fire damage to creatures that fail a Reflex save. Creatures that save take half damage. This spell has no effect in vacuum, deals half damage in normal and thin atmosphere, and deals full damage in thick atmosphere and underwater."},"flesh_to_stone":{"name":"Flesh to Stone","level":6,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Flesh%20to%20Stone","src":"CRB pg. 355","summary":"You fire a dull gray ray at your target, making a ranged attack against your target’s EAC, but you can add your key ability score bonus to this attack instead of your Dexterity modifier if it is higher."},"flight":{"name":"Flight","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Flight","src":"CRB pg. 355","summary":"You tinker with the particles of magic surrounding one or more targets to either allow them to slow a fall, gently rise or descend, or fly short or vast distances."},"fluid_morphism":{"name":"Fluid Morphism","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fluid%20Morphism","src":"GM pg. 74","summary":"Lashuntas experimented with this magic based on their species’ dimorphism. With this spell, you reignite the epigenetic processes that shaped the target and alter them, applying different environmental pressures to temporarily awaken dormant potential in the genetic code. Choose one ability score."},"fluidity_of_form":{"name":"Fluidity Of Form","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fluidity%20Of%20Form","src":"GM pg. 74","summary":"Drawing upon the ever-shifting chaos of the Maelstrom, you free the target from the shackles of their form. Each round at the start of their turn, the target must select one of the following benefits they gain for that round. They can’t select the same benefit on two consecutive rounds."},"fluidity_of_form_mass":{"name":"Fluidity Of Form, Mass","level":5,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fluidity%20Of%20Form%2C%20Mass","src":"GM pg. 74","summary":"This spell functions like Fluidity Of Form, except as noted above. Fluidity Of Form Drawing upon the ever-shifting chaos of the Maelstrom, you free the target from the shackles of their form."},"flux_density":{"name":"Flux Density","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Flux%20Density","src":"AP #36 pg. 52","summary":"When you cast flux density, choose rise or sink. If you choose rise, each target ascends 10 feet per round, or if you choose sink, each target sinks 10 feet per round; this movement doesn’t provoke attacks of opportunity."},"fog_cloud":{"name":"Fog Cloud","level":2,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Fog%20Cloud","src":"CRB pg. 356","summary":"A bank of fog billows out from the point you designate. The fog obscures all sight, including darkvision, beyond 5 feet. Adjacent creatures are granted concealment against one another (attacks have a 20% miss chance)."},"force_blast":{"name":"Force Blast","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Force%20Blast","src":"CRB pg. 356","summary":"You gather mystical energy and blast it outward in a mighty wave originating from your fingertips, damaging and potentially knocking back your enemies. This spell deals 2d6 force damage to each creature in the area unless it succeeds at a Reflex saving throw for half damage."},"forcecage":{"name":"Forcecage","level":6,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Forcecage","src":"GM pg. 74","summary":"You create an immobile, invisible but hollow cube of force composed of bars or solid walls (your choice). Creatures within the area are caught and contained."},"forceful_fling":{"name":"Forceful Fling","level":3,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Forceful%20Fling","src":"SA:RR pg. 59","summary":"You fling a willing ally across the battlefield, moving them 30 feet in a straight line from its original position to an unoccupied square in range."},"furious_shriek":{"name":"Furious Shriek","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Furious%20Shriek","src":"GM pg. 75","summary":"Orcs and half-orcs learned long ago to channel rage, despair, or a sense of injustice or oppression into a soul-shaking shriek. The shriek deals sonic damage to creatures and objects based on the spell slot used to cast the spell."},"ghost_sound":{"name":"Ghost Sound","level":0,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ghost%20Sound","src":"CRB pg. 356","summary":"You create a volume of sound that rises, falls, recedes, approaches, or remains fixed. You choose what type of sound this spell creates when casting it and cannot thereafter change the sound’s basic character. The volume of sound created can produce as much noise as 20 normal humans."},"glimpse_of_truth":{"name":"Glimpse Of Truth","level":3,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Glimpse%20Of%20Truth","src":"AP #25 pg. 45","summary":"This spell functions as True Seeing, except as noted in Details. True Seeing You confer upon the target the ability to see all things within 120 feet as they actually are."},"gloom_mote":{"name":"Gloom Mote","level":1,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Gloom%20Mote","src":"AP #12 pg. 53","summary":"You draw forth the energy of the Shadow Plane and form it into a floating mote of gloom. The mote creates dim light in a 5-foot radius. It also lowers the light level within 20 feet of it by one step, down to dim. As a move action, you can move the mote up to 60 feet in any direction."},"glowing_wall":{"name":"Glowing Wall","level":0,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Glowing%20Wall","src":"GM pg. 75","summary":"A barrier of light, colored as you choose, springs into existence. You can form the wall into a vertical or horizontal plane, but each 10-foot square must join another. The light level within 5 feet of the wall increases to normal light."},"grasping_brambles":{"name":"Grasping Brambles","level":4,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Grasping%20Brambles","src":"AP #42 pg. 42","summary":"You entrap a creature in a cage of thorny brambles that erupts from the ground around them. The target must attempt a Reflex save. On a successful save, the target takes 2d6 piercing damage as it escapes the brambles and the spell ends."},"grave_words":{"name":"Grave Words","level":0,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Grave%20Words","src":"CRB pg. 357","summary":"You can force a touched corpse talk to you, but you can’t ask it specific questions or communicate with it at all. The corpse utters random sentences for 1 round, with a 10% chance this information is of some use to you."},"gravitational_singularity":{"name":"Gravitational Singularity","level":6,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Gravitational%20Singularity","src":"CRB pg. 357","summary":"You call into being a tiny particle of mass with infinite density. You must conjure the singularity in a square that is unoccupied by any creatures or objects."},"gravity_tether":{"name":"Gravity Tether","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Gravity%20Tether","src":"GM pg. 75","summary":"By manipulating electromagnetic forces acting on your target, you change its movements. Attempt a melee attack against EAC. If you attempt a full attack, you can target two creatures. On a hit, your target takes 5d8 electricity damage and must attempt a Reflex save."},"gravity_well":{"name":"Gravity Well","level":4,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Gravity%20Well","src":"COM pg. 135","summary":"You alter the gravity in an area, making a central point of high gravity that pulls creatures toward it. Each creature in the area when the spell takes effect is knocked Prone unless it succeeds at a Reflex saving throw."},"grease":{"name":"Grease","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Grease","src":"CRB pg. 357","summary":"You cover a solid surface with a layer of slippery grease. Any creature in the area when the spell is cast must succeed at a Reflex save or fall Prone. A creature can walk within or through the area of grease at half normal speed with a successful DC 10 Acrobatics check."},"grim_insight":{"name":"Grim Insight","level":3,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Grim%20Insight","src":"GM pg. 75","summary":"You channel visions of a grim future into your target’s mind. Attempt a melee attack against the target’s EAC, adding the higher of your key ability modifier or your Strength modifier to the attack roll. On a hit, the target takes 6d10 damage and must attempt a Will saving throw."},"groundling":{"name":"Groundling","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Groundling","src":"COM pg. 135","summary":"The target’s body forms an exoskeleton, and its appendages such as hands and feet become broad and pointed like spades. Armor that covers any of these appendages functions normally and molds to fit the appendages’ new shape."},"gyre":{"name":"Gyre","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Gyre","src":"AP #36 pg. 52","summary":"You cause the water in gyre’s area of effect to form a twisting whirlpool that drags creatures in and down. Each creature that enters or starts its turn in the spell’s area must attempt a Reflex save."},"hack_wetware":{"name":"Hack Wetware","level":2,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hack%20Wetware","src":"AP #25 pg. 52","summary":"If the target fails its saving throw, you form a link between their mind and a computer you touch at the time of casting, allowing you to hack their brain as if it were a computer to examine or manipulate memories and implant suggestions."},"hailstorm":{"name":"Hailstorm","level":5,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hailstorm","src":"AA4 pg. 119","summary":"A barrage of fist-sized hailstones pelts the area. Creatures that enter or start their turn in the area during the first round of the spell take 6d8 cold damage and 7d8 bludgeoning damage. For the remaining duration of the spell, heavy snow and sleet rain down in the area."},"handy_junkbot":{"name":"Handy Junkbot","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Handy%20Junkbot","src":"CRB pg. 357","summary":"You turn a pile of technological junk into a robot that can accomplish helpful tasks. You must target inert, nonworking electronic equipment of at least 1 bulk."},"hardlight_spheres":{"name":"Hardlight Spheres","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hardlight%20Spheres","src":"EN pg. 123","summary":"You create 4 small glowing spheres that orbit your head for the duration of the spell, emitting normal light in a 10-foot radius. As a swift action, you can launch one of the spheres, making a ranged attack targeting KAC with a range of 60 feet."},"harness_lightning":{"name":"Harness Lightning","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Harness%20Lightning","src":"GM pg. 75","summary":"Born of necessity to contend with violent storms on the world of Shimrinsara in the Vast,harness lightningenables you to collect energy from major electrical discharges that occur within the area of the spell."},"haste":{"name":"Haste","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Haste","src":"CRB pg. 358","summary":"The targeted creatures move and act more quickly than normal. This extra speed has several effects. When making a full attack, a hasted creature can also take a separate move action in order to move. The movement can occur before, after, or between the attacks from the full attack."},"hateful_visage":{"name":"Hateful Visage","level":4,"school":"ill","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hateful%20Visage","src":"COM pg. 135","summary":"You pull alternate forms from horrifying realities and drape them upon the target, causing the target to exhibit almost any type of body horror imaginable. Your allies can tell this effect results from your layering of alternate realities onto this one and are unaffected."},"haunted_armor":{"name":"Haunted Armor","level":2,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Haunted%20Armor","src":"COM pg. 136","summary":"You divert a malevolent spirit from the River of Souls to haunt your opponent’s armor. This spell must target a suit of light, heavy, or powered armor. The armor becomes cumbersome, reducing the wearer’s speed by 10 feet and AC by 1."},"haunted_combatant":{"name":"Haunted Combatant","level":2,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Haunted%20Combatant","src":"COM pg. 136","summary":"You divert a malevolent spirit from the River of Souls to temporarily haunt and interfere with an opponent’s weapons. The spirit writhes and rattles around in the target’s manufactured weapons, imposing a –1 penalty on the target’s attack rolls with weapons other than natural weapons."},"hazard":{"name":"Hazard","level":0,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hazard","src":"COM pg. 136","summary":"When you cast this spell, choose acid, cold, electricity, fire, or sonic. The spell gains that descriptor. You summon a minor hazard from an alternate reality, creating a splash of acid rain, a blast of freezing air, a static electric discharge, a burst of fire, or a roar of thunder."},"healing_junkbot":{"name":"Healing Junkbot","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Healing%20Junkbot","src":"CRB pg. 358","summary":"You turn a pile of technological junk into a robot that can perform basic healing tasks. You must target inert, nonworking electronic equipment of at least 1 bulk."},"heat_leech":{"name":"Heat Leech","level":5,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Heat%20Leech","src":"CRB pg. 359","summary":"You drain the heat from all creatures and objects in the area, dealing 13d8 cold damage. You can store the gathered heat energy in a used battery. If you do so and use that battery when casting explosive blast within 1 minute, that spell deals 2d6 additional fire damage, destroying the used battery."},"helping_hands":{"name":"Helping Hands","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Helping%20Hands","src":"GM pg. 76","summary":"First developed by resourceful skittermander technomancers, you or a targeted creature sprout two vestigial hands that can hold and manipulate objects. While this spell is active, the target gains a +2 circumstance bonus to Engineering and Sleight of Hand checks."},"helping_hands_mass":{"name":"Helping Hands, Mass","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Helping%20Hands%2C%20Mass","src":"GM pg. 76","summary":"This spell functions as Helping Hands, except as noted above. Helping Hands First developed by resourceful skittermander technomancers, you or a targeted creature sprout two vestigial hands that can hold and manipulate objects."},"hide_weapon":{"name":"Hide Weapon","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hide%20Weapon","src":"AP #35 pg. 54","summary":"When you cast this spell, a small arm or one-handed melee weapon with the operative special property in your hand melds with your flesh, accompanied by a disgusting sucking sound. The weapon can be no greater than light bulk, and it disappears completely inside your arm."},"hold_monster":{"name":"Hold Monster","level":4,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hold%20Monster","src":"CRB pg. 359","summary":"This spell functions as Hold Person, except it can target any living creature. Hold Person The target becomes Paralyzed and freezes in place. It is aware and breathes normally but can’t take any physical actions, even speech. A held creature can’t cast spells."},"hold_person":{"name":"Hold Person","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hold%20Person","src":"CRB pg. 359","summary":"The target becomes Paralyzed and freezes in place. It is aware and breathes normally but can’t take any physical actions, even speech. A held creature can’t cast spells. Each round on its turn, the target can spend a full action to attempt a new saving throw to end the effect."},"hold_portal":{"name":"Hold Portal","level":1,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hold%20Portal","src":"CRB pg. 359","summary":"This spell magically holds shut a door, gate, shutter, or window of any standard material (metal, plastic, stone, wood, and so on), or it reinforces an electronic lock. The magic affects the portal just as if it were securely closed and normally locked."},"hologram_memory":{"name":"Hologram Memory","level":3,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hologram%20Memory","src":"CRB pg. 359","summary":"You reach into the target’s mind, extract a specific memory, and project that memory into a small hologram that plays in front of you and is visible to all creatures who can see it."},"holographic_image":{"name":"Holographic Image","level":1,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Holographic%20Image","src":"CRB pg. 360","summary":"You weave nearby photons into illusory holograms that can take almost any form you can imagine. These holograms are usually effective against cameras, robots, and living creatures."},"holographic_interface":{"name":"Holographic Interface","level":0,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Holographic%20Interface","src":"GM pg. 76","summary":"You conjure a holographic interface you can use to communicate with the target computer. The interface allows you to operate an unfamiliar computer or one that lacks an interface as though you did have an interface, but it doesn’t change your level of access."},"holographic_terrain":{"name":"Holographic Terrain","level":5,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Holographic%20Terrain","src":"CRB pg. 360","summary":"You make terrain look, sound, and smell like some other sort of terrain. Equipment, structures, and vehicles within the area can be hidden or changed in appearance."},"hoverdisk":{"name":"Hoverdisk","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hoverdisk","src":"COM pg. 136","summary":"You create a thin, circular plane of force 3 feet in diameter and able to hover up to 3 feet above the ground."},"hoverdisk_mass":{"name":"Hoverdisk, Mass","level":5,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hoverdisk%2C%20Mass","src":"COM pg. 137","summary":"This spell functions as Hoverdisk, except as noted above. As part of casting this spell, you can give a single set of instructions to all disks, or you can give separate instructions to each disk."},"hurl_forcedisk":{"name":"Hurl Forcedisk","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Hurl%20Forcedisk","src":"CRB pg. 360","summary":"You create a spinning disk made of pure, shimmering force and hurl it at one opponent within range, potentially striking other nearby enemies as the disk ricochets. Choose the initial target, and make a ranged attack against its EAC. If the attack hits, the disk deals 3d6 force damage."},"ice_bolt":{"name":"Ice Bolt","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ice%20Bolt","src":"AP #36 pg. 52","summary":"You cause the ambient atmosphere or water to flash freeze, creating a jagged icicle that deals 5d6 cold and 5d6 piercing to each creature in its area. When cast underwater, this spell deals an additional 2d6 cold damage."},"ice_prison":{"name":"Ice Prison","level":6,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ice%20Prison","src":"GM pg. 76","summary":"You encase a creature in a block of ice. The creature takes 8d6 cold damage and becomes paralyzed. A creature that succeeds at a Reflex saving throw halves the damage it takes and avoids becoming paralyzed."},"id_insinuation":{"name":"Id Insinuation","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Id%20Insinuation","src":"AP #23 pg. 52","summary":"By invading targets with your psychic presence, you isolate parts of their minds, preventing them from functioning in a coherent manner. Targets who fail their save are Confused for the duration."},"identify":{"name":"Identify","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Identify","src":"CRB pg. 361","summary":"This spell allows you to attempt to identify the function of a magic item (with Mysticism) or technological device (with Engineering) each round. You gain a +10 insight bonus to skill checks to identify the properties and command words or passwords of items targeted when using this spell."},"identity_storm":{"name":"Identity Storm","level":4,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Identity%20Storm","src":"PoC pg. 123","summary":"This spell causes all creatures in the area to perceive all other creatures as copies of someone they have a strong impression of, whether a friend, enemy, or even themselves."},"illusory_star_field":{"name":"Illusory Star Field","level":1,"school":"ill","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Illusory%20Star%20Field","src":"COM pg. 137","summary":"This spell causes targets to see an illusory star pattern, naturally occurring space phenomena, or another general skyscape you choose the details of during casting."},"implant_data":{"name":"Implant Data","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Implant%20Data","src":"CRB pg. 361","summary":"You subtly rearrange the internal circuitry of a computer system or module, programming it to convey a certain dataset when accessed (either normally or if it is hacked). You can implant up to one piece of data per caster level."},"incompetence":{"name":"Incompetence","level":1,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Incompetence","src":"AR pg. 157","summary":"You cause all targets of this spell to lose proficiency with one class of weapons of your choice (basic or advanced melee weapons, small arms, longarms, heavy weapons, grenades, or natural weapons) and suffer the normal penalties for attacks made with weapons they are not proficient with."},"infect_blood":{"name":"Infect Blood","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Infect%20Blood","src":"COM pg. 137","summary":"You alter the target’s internal chemistry, causing their body to reject its composition. The target takes 3d8 damage each round, but can attempt a Fortitude save for half damage, and has the Sickened condition for the duration."},"inflame":{"name":"Inflame","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Inflame","src":"AA4 pg. 19","summary":"You make a melee attack against a single target’s EAC. If you hit, the target must succeed at a Fortitude save or it is sickened and develops painful blisters and boils that last for the spell’s duration."},"inflict_pain":{"name":"Inflict Pain","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Inflict%20Pain","src":"CRB pg. 361","summary":"You telepathically rack the target’s mind and body with agonizing pain that imposes a –2 penalty to ability checks, attack rolls, and skill checks. A target that succeeds at a Will saving throw reduces the duration to 1 round."},"inflict_pain_mass":{"name":"Inflict Pain, Mass","level":6,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Inflict%20Pain%2C%20Mass","src":"CRB pg. 361","summary":"This spell functions as Inflict Pain, except as noted above. Inflict Pain You telepathically rack the target’s mind and body with agonizing pain that imposes a –2 penalty to ability checks, attack rolls, and skill checks. A target that succeeds at a Will saving throw reduces the duration to 1 round."},"inject_nanobots":{"name":"Inject Nanobots","level":2,"school":"nec","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Inject%20Nanobots","src":"CRB pg. 361","summary":"You concentrate key particles in your blood into tiny biological nanobots that you can inject into a foe with a touch, disrupting and damaging its natural processes."},"injury_echo":{"name":"Injury Echo","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Injury%20Echo","src":"GM pg. 76","summary":"You manifest an injury from the target’s future or past. Choose bludgeoning, piercing, or slashing when you cast this spell. The target must succeed at a Will saving throw or take 1d6 damage of the chosen type."},"instant_upgrade":{"name":"Instant Upgrade","level":2,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Instant%20Upgrade","src":"COM pg. 137","summary":"You conjure bits of technology infused with magic to create one functional, temporary cybernetic augmentation with a level equal to or lower than your caster level. You decide which cybernetic augmentation to create when you cast this spell."},"instant_virus":{"name":"Instant Virus","level":3,"school":"nec","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Instant%20Virus","src":"CRB pg. 361","summary":"You overwhelm your target’s programming, installing a dangerous self-replicating programming virus. This works like a physical or mental Disease (your choice), except it ignores the target’s immunity to Diseases."},"intellect_fortress":{"name":"Intellect Fortress","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Intellect%20Fortress","src":"AP #23 pg. 52","summary":"When you or a creature within range is subjected to a mind‑affecting effect while this spell is active, you disrupt it with the power of pure logic."},"interplanetary_teleport":{"name":"Interplanetary Teleport","level":6,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Interplanetary%20Teleport","src":"CRB pg. 362","summary":"This spell functions as teleport, except there is no hard range limit and you don’t need to have seen your destination. You can teleport to anywhere you are familiar with on the planet you are on while casting the spell, or you can teleport to any other planet in the same solar system."},"invisibility":{"name":"Invisibility","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Invisibility","src":"CRB pg. 362","summary":"The creature or object touched becomes invisible (see page 264). If the target is a creature, any gear it is carrying vanishes as well. If you cast the spell on someone else, neither you nor your allies can see the target unless you can normally see invisible things or you employ magic to do so."},"invisibility_greater":{"name":"Invisibility, Greater","level":4,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Invisibility%2C%20Greater","src":"CRB pg. 362","summary":"This spell functions like Invisibility, except it doesn’t end if the target attacks. Invisibility The creature or object touched becomes invisible (see page 264). If the target is a creature, any gear it is carrying vanishes as well."},"invisibility_mass":{"name":"Invisibility, Mass","level":6,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Invisibility%2C%20Mass","src":"CRB pg. 362","summary":"This spell functions like Invisibility, except the effect moves with the group and is broken when anyone in the group attacks. Individuals in the group can’t see one another. Any individual who moves more than 180 feet from the nearest member of the group loses the benefit of this spell."},"invisibility_to_technology":{"name":"Invisibility To Technology","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Invisibility%20To%20Technology","src":"COM pg. 137","summary":"The target and its gear cannot be detected by cameras, motion detectors, technological armor upgrades such as infrared sensors, biotech and cybernetic eyes or ears, or other technological devices, and it is invisible to constructs with the technological subtype."},"irradiate":{"name":"Irradiate","level":3,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Irradiate","src":"CRB pg. 362","summary":"This spell floods the area of effect with dangerous radiation. The strength of the radiation you create depends on your caster level, as detailed below. The central irradiated area is always a 10-foot-radius spread that expands normally per the rules for radiation areas of effect (see page 403)."},"jolting_surge":{"name":"Jolting Surge","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Jolting%20Surge","src":"CRB pg. 363","summary":"You touch a target with a device you’re holding that uses electricity, requiring a melee attack against the target’s EAC."},"junk_armor":{"name":"Junk Armor","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Armor","src":"PW pg. 205","summary":"You turn a pile of technological junk into a suit of light armor, or use it to upgrade a suit of light armor to heavy armor. You must target inert, nonworking electronic equipment of at least 1 bulk."},"junk_barricade":{"name":"Junk Barricade","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Barricade","src":"SA:JD pg. 58","summary":"You turn a pile of technological junk into a barricade that provides cover. You must target inert, nonworking electronic equipment of at least 1 bulk. The junk you target stacks and reinforces itself to form a low wall along one edge of your square."},"junk_bomb":{"name":"Junk Bomb","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Bomb","src":"EN pg. 123","summary":"You energize a small pile of junk (such as material to create a handy junkbot) or junk device created by one of your technomancer spells (such as handy junkbot or junksword PW )."},"junk_grenande":{"name":"Junk Grenande","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Grenande","src":"PoC pg. 83","summary":"You transform a pile of technological junk into three grenades. You must target inert, nonworking electronic equipment of at least 1 bulk."},"junk_restraints":{"name":"Junk Restraints","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Restraints","src":"NS pg. 156","summary":"You turn a pile of technological junk into fetters and shackles that restrain a creature within range. You must target inert, nonworking electronic equipment of at least 1 bulk."},"junk_shanty":{"name":"Junk Shanty","level":5,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Shanty","src":"SA:JD pg. 58","summary":"You turn a pile of technological junk into an extradimensional shelter. You must target inert, nonworking electronic equipment of at least 1 bulk."},"junk_shards":{"name":"Junk Shards","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junk%20Shards","src":"NS pg. 156","summary":"You summon sharp fragments of technological junk that fly toward your target and deal 3d6 piercing and slashing damage."},"junksword":{"name":"Junksword","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Junksword","src":"PW pg. 205","summary":"You turn a pile of technological junk into a one-handed melee weapon that you can wield against your foes. You must target inert, nonworking electronic equipment of at least 1 bulk."},"keen_senses":{"name":"Keen Senses","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Keen%20Senses","src":"CRB pg. 363","summary":"The target gains a +2 insight bonus to Perception checks and gains low-light vision. Targets that have low-light vision double the distance they can see under the effects of this spell."},"knock":{"name":"Knock","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Knock","src":"CRB pg. 363","summary":"Knock opens barred, computer-sealed, locked, or stuck doors, as well as those subject to hold portal or security seal. When you complete the casting of this spell, attempt a caster level check (1d20 + your caster level) against the DC of the lock or computer seal with a +10 bonus."},"know_coordinates":{"name":"Know Coordinates","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Know%20Coordinates","src":"COM pg. 137","summary":"You learn the general location of one creature on the same planetary body as you, up to the size of a large planet, such as a gas giant. You must be able to identify the creature clearly from personal knowledge of who they are."},"laser_net":{"name":"Laser Net","level":2,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Laser%20Net","src":"COM pg. 137","summary":"This spell creates a net of dangerous lasers between two solid points. The net can appear only if there are appropriate anchoring surfaces at both ends of the beams, such as two walls, a wall and a ceiling, or the like. Otherwise, the spell fails."},"last_gasp":{"name":"Last Gasp","level":2,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Last%20Gasp","src":"AP #36 pg. 52","summary":"You can cast last gasp within range would die from suffocation. They instead begin attempting Constitution checks as though they had just run out of air (including resetting the DC of such checks to 10)."},"lava_floor":{"name":"Lava Floor","level":6,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Lava%20Floor","src":"EN pg. 123","summary":"You transform the ground or floor into a pool of lava about one foot deep. Creatures in contact with the ground when you cast the spell take 6d12 fire damage (Reflex half), after which they are immune to additional fire damage from beginning their turn in the area for 1 round."},"life_bubble":{"name":"Life Bubble","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Life%20Bubble","src":"CRB pg. 363","summary":"You surround the target creatures with a constant and movable 1-inch shell of tolerable living conditions customized for each creature."},"lifeforce_reservoir":{"name":"Lifeforce Reservoir","level":2,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Lifeforce%20Reservoir","src":"EN pg. 123","summary":"You siphon part of your lifeforce into an unseen reservoir. When you cast this spell, roll 2d8 and reduce your current and maximum Hit Point totals by the result."},"lifting_frame":{"name":"Lifting Frame","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Lifting%20Frame","src":"COM pg. 138","summary":"You create a holographic lifting frame around the target to subtly reinforce the target’s musculature and posture. For the duration, the target’s Strength modifier is +5 for carrying capacity and destroying objects using Strength."},"locate_hive":{"name":"Locate Hive","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Locate%20Hive","src":"GM pg. 76","summary":"This spell was created by formian myrmarchs to prevent workers from getting lost when sent far afield. When you cast this spell, you designate a specific building as your hive. Your hive must be a familiar structure (or starship) that you can picture clearly in your mind."},"logic_bomb":{"name":"Logic Bomb","level":2,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Logic%20Bomb","src":"CRB pg. 364","summary":"You infuse one computer system or module with protective energy, inuring it against attempts to access it."},"magic_mark":{"name":"Magic Mark","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Magic%20Mark","src":"GM pg. 76","summary":"You place a magical mark, about 1 square foot in size, on the target. When you create it, the mark can be visible, invisible, or invisible to everyone but you. A visible mark can be something electronically readable, such as a barcode."},"magic_missile":{"name":"Magic Missile","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Magic%20Missile","src":"CRB pg. 364","summary":"You fire two missiles of magical energy that strike targets unerringly (the creatures must still be valid targets) and deal 1d4+1 force damage each. You can’t target specific parts of a creature, and objects are not damaged by the spell."},"magic_seal":{"name":"Magic Seal","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Magic%20Seal","src":"GM pg. 76","summary":"You place a seal on a creature, possibly preventing it from casting spells (including from magic items), using spell-like abilities, and using supernatural abilities that affect anything other than it."},"magic_seal_greater":{"name":"Magic Seal, Greater","level":6,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Magic%20Seal%2C%20Greater","src":"GM pg. 77","summary":"You create a seal that suppresses magic in an area, which radiates from a creature or an object and moves with that target. An unwilling target can attempt a saving throw against this spell and use its spell resistance, and the sealed area fails to manifest if either defense works."},"make_mischief":{"name":"Make Mischief","level":2,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Make%20Mischief","src":"AP #35 pg. 55","summary":"While this spell lasts, nearly invisible tendrils of energy surround you. As part of casting this spell or as a move action once per round, you can direct the energy to do one of the following. Attempt a dirty trick combat maneuver as a melee attack against an adjacent creature."},"make_whole":{"name":"Make Whole","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Make%20Whole","src":"CRB pg. 364","summary":"This spell functions as Mending, except it restores 5d6 Hit Points when cast on an object or construct creature. Make whole can fix destroyed magic items, and it restores the magic properties of the item if your technomancer level is at least twice the item’s level."},"manipulate_tech":{"name":"Manipulate Tech","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Manipulate%20Tech","src":"COM pg. 138","summary":"You can briefly align your will to the circuitry or structure of an unattended technological weapon or a technological item with a usage entry, provided the target has an item level equal to or lower than your caster level + 3. The target can even have the broken condition."},"measure":{"name":"Measure","level":0,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Measure","src":"GM pg. 77","summary":"You learn the approximate measurements (length, width, depth, height, mass) of creatures and objects you can observe in the area. If an object or creature extends out of the area, you learn only the measurements within the area but nothing about what you can’t observe."},"megavitamin":{"name":"Megavitamin","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Megavitamin","src":"COM pg. 138","summary":"You create 2d4 powerful vitamins. One of these supplements meets its eater’s food needs for 24 hours and causes the eater to regain 1 Hit Point. A creature can regain no more than 8 Hit Points from any megavitamin spell in a 24-hour period."},"memory_lapse":{"name":"Memory Lapse","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Memory%20Lapse","src":"AP #25 pg. 53","summary":"You inspire a moment of confusion that causes a creature to forget what occurred over the last round if it fails its saving throw."},"memory_prism":{"name":"Memory Prism","level":4,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Memory%20Prism","src":"IS pg. 123","summary":"You copy one memory you have and cause it to crystallize into a small prism of negligible bulk."},"mending":{"name":"Mending","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mending","src":"CRB pg. 364","summary":"This spell repairs damaged objects and constructs, restoring 1d4 Hit Points. If the object has the broken condition, this condition is removed if the object is restored to at least half its original Hit Points. All of the pieces of an object must be present for this spell to function."},"mental_block":{"name":"Mental Block","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mental%20Block","src":"PW pg. 206","summary":"You cause targets of this spell to lose access to their procedural memory, preventing them from using any feat, extraordinary ability, spell, spell-like ability, or supernatural ability that requires an action of any kind."},"mental_muscle":{"name":"Mental Muscle","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mental%20Muscle","src":"IS pg. 63","summary":"You channel your mental mastery as magic that directly reinforces your body, allowing you to perform brief physical feats as acts of willpower. You gain one of the following three benefits of your choice."},"mental_muscle_greater":{"name":"Mental Muscle, Greater","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mental%20Muscle%2C%20Greater","src":"IS pg. 63","summary":"This spell functions as mental muscle, except as noted above. Casting this spell takes intense focus and requires you to spend 1 Resolve Point. You channel your mental mastery as magic that directly reinforces your body, allowing you to perform brief physical feats as acts of willpower."},"mental_silence":{"name":"Mental Silence","level":1,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mental%20Silence","src":"COM pg. 22","summary":"You create an anti-telepathic field around yourself."},"merge_consciousness":{"name":"Merge Consciousness","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Merge%20Consciousness","src":"AP #29 pg. 45","summary":"You merge your consciousness with one touched creature, sharing your strengths and compensating for each other's weaknesses."},"meticulous_match":{"name":"Meticulous Match","level":3,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Meticulous%20Match","src":"AP #25 pg. 45","summary":"You compare two similar items and know if they are identical to one another or not. The spell can indicate an identical match, a categorical match, or no match. For instance, blood samples are identical if they are from the same creature. They are categorical if they are from the same species."},"miasma":{"name":"Miasma","level":4,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Miasma","src":"COM pg. 138","summary":"You turn the atmosphere in your immediate area into a hazy, green miasma that does not flow like normal air. It instead remains in its area for the duration and penetrates armor Environmental protections. Creatures within the miasma have concealment against attackers."},"microbot_assault":{"name":"Microbot Assault","level":2,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Microbot%20Assault","src":"CRB pg. 364","summary":"You pull latent technological energy from the air to form a cloud of fist-sized hindering microbots that fill an area you designate. The microbots begin in a 10-foot-square area when you create them, and you can create the cloud so that it shares the space of other creatures."},"might_of_the_ellicoth":{"name":"Might Of The Ellicoth","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Might%20Of%20The%20Ellicoth","src":"PW pg. 206","summary":"With a touch, you cause a surge of power to flow through the target’s slow-twitch muscle fiber (or its equivalent physiology if it has no muscle fibers), increasing the amount of bulk the creature can carry by 3."},"mind_of_three":{"name":"Mind Of Three","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mind%20Of%20Three","src":"AP #22 pg. 52","summary":"You split your mind, retaining your normal consciousness but gaining two other personas. These personas are nearly identical to your original personality, but each emphasize a different aspect of your personality."},"mind_probe":{"name":"Mind Probe","level":4,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mind%20Probe","src":"CRB pg. 365","summary":"You gain access to the target’s memories and knowledge, and you can pry the information you want from them involuntarily. You can attempt to learn the answer to one question of your choice per round; after each question, the target can attempt a Will saving throw to end the spell."},"mind_swap":{"name":"Mind Swap","level":6,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mind%20Swap","src":"AA3 pg. 137","summary":"Your mind moves into the target’s body, and its mind moves into yours. You do not need line of sight or line of effect to the target if you know its location. Each target gains the Mind-Swapped template graft. You can maintain the swap at any range on the same plane."},"mind_thrust":{"name":"Mind Thrust","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mind%20Thrust","src":"CRB pg. 365","summary":"You divine the most vulnerable portion of your opponent’s mind and overload it with a glut of psychic information. The target can attempt a Will saving throw to halve the damage dealt by this spell. This spell has no effect on creatures without an Intelligence score."},"mindlink":{"name":"Mindlink","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mindlink","src":"CRB pg. 365","summary":"You link your mind to that of a touched creature to swiftly communicate a large amount of complex information in an instant. You decide what the target learns, limited to any amount of information that otherwise could be communicated in 10 minutes."},"minibot_messenger":{"name":"Minibot Messenger","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Minibot%20Messenger","src":"PoC pg. 83","summary":"You conjure a miniature messenger robot that appears in your space. The robot is a Tiny construct with the technological subtype."},"miracle":{"name":"Miracle","level":6,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Miracle","src":"CRB pg. 366","summary":"When you cast miracle, you state what you would like to have happen and request that the power to which you are connected intercede. A request that is out of line with the power’s nature is refused. A miracle can do any of the following things. Duplicate any mystic spell of 6th level or lower."},"mirror_image":{"name":"Mirror Image","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mirror%20Image","src":"CRB pg. 366","summary":"This spell creates a number of illusory doubles of you that inhabit your square. These doubles make it difficult for enemies to precisely locate and attack you. When you cast mirror image, it creates 1d4 figment images."},"misfire":{"name":"Misfire","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Misfire","src":"GM pg. 77","summary":"The next time the targeted object is used in a way that consumes charges or ammo, the device fails to work. A weapon fails to fire or operate, or a technological device doesn’t respond to its activation. This spell ends once it prevents the targeted object from working that one time."},"mislead":{"name":"Mislead","level":5,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mislead","src":"CRB pg. 366","summary":"You become invisible (as Invisibility, Greater), and at the same time, a figment double of you (as per a 3rd-level casting of Holographic Image) appears."},"modify_memory":{"name":"Modify Memory","level":5,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Modify%20Memory","src":"CRB pg. 366","summary":"You reach into the target’s mind and modify up to 5 minutes of its memories in one of the following ways. Eliminate all memory of an event the target actually experienced. This spell cannot negate Charm Person, suggestion, or similar spells."},"modify_outcome":{"name":"Modify Outcome","level":4,"school":"div","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Modify%20Outcome","src":"NS pg. 156","summary":"You peer across the multiverse at the possible outcomes for this timeline, watching fate branch outward. When an ally within range fails an attack roll, skill check, saving throw, or ability check, you can spend 1 Resolve Point to attempt to shift their reality to one where they succeed instead."},"modulate_frequency":{"name":"Modulate Frequency","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Modulate%20Frequency","src":"GM pg. 77","summary":"At dire risk from certain sonic frequencies, a conclave of quorlu mystics devised the modulate frequency spell, which enables you to change the frequencies of the sounds emitted by the target object or creature."},"moment's_hesitation":{"name":"Moment's Hesitation","level":0,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Moment%27s%20Hesitation","src":"EN pg. 123","summary":"You instill intense feelings of uncertainty in a creature, giving them the Staggered condition for 1 round (Will negates). The first time the staggered creature takes damage before their next turn, they can attempt a second Will save to immediately end the effect."},"mystic_cure":{"name":"Mystic Cure","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mystic%20Cure","src":"CRB pg. 367","summary":"With a touch, you heal and invigorate your target, restoring a number of Hit Points. If the target regains all of its Hit Points as a result of this healing, you can apply the remaining healing to yourself, as long as you are a living creature."},"mystic_cure_mass":{"name":"Mystic Cure, Mass","level":5,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mystic%20Cure%2C%20Mass","src":"CRB pg. 367","summary":"You restore a number of Hit Points to a number of targets. Choose one of these targets within 10 feet of you; if that target regains all of its Hit Points as a result of this healing, you can apply the remaining healing to yourself, as long as you are a living creature."},"mystical_aegis":{"name":"Mystical Aegis","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mystical%20Aegis","src":"GM pg. 78","summary":"You grant the target a barrier that deflects magic and absorbs supernatural damage. While it lasts, the barrier grants the target a +2 morale bonus to saving throws against spells, spell-like abilities, and supernatural abilities."},"mystical_aegis_greater":{"name":"Mystical Aegis, Greater","level":6,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mystical%20Aegis%2C%20Greater","src":"GM pg. 78","summary":"This spell functions as Mystical Aegis, but it provides the benefits of a Death Wardspell and has 100 temporary Hit Points Mystical Aegis You grant the target a barrier that deflects magic and absorbs supernatural damage."},"mystical_aegis_mass":{"name":"Mystical Aegis, Mass","level":5,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Mystical%20Aegis%2C%20Mass","src":"GM pg. 78","summary":"This spell functions as Mystical Aegis except as noted above. Mystical Aegis You grant the target a barrier that deflects magic and absorbs supernatural damage."},"nanite_form":{"name":"Nanite Form","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Nanite%20Form","src":"COM pg. 138","summary":"The target and its gear are transformed into a cloud of nanites that fills a 5-foot cube."},"necromantic_revitalization":{"name":"Necromantic Revitalization","level":1,"school":"nec","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Necromantic%20Revitalization","src":"PW pg. 206","summary":"With a touch, you replenish the negative energies that animate your target, restoring a number of Hit Points. If the target regains all of its Hit Points as a result of this healing, you can apply the remaining healing to yourself, as long as you are an undead creature."},"negate_spell":{"name":"Negate Spell","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Negate%20Spell","src":"GM pg. 78","summary":"You interpose your will between the casting of a spell and the magical energies powering that spell, preventing it from manifesting in this reality. As a reaction when you observe a spell that’s 3rd level or lower and being cast within range, you can cast this spell."},"nightmare":{"name":"Nightmare","level":3,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Nightmare","src":"AP #10 pg. 53","summary":"You precisely identify a target, such as by name or via a material connection like a personal possession or lock of its hair. The spell fails without expending a spell slot if the target isn’t Asleep or in a resting state similar to sleep."},"nondetection":{"name":"Nondetection","level":3,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Nondetection","src":"CRB pg. 367","summary":"The warded creature or object becomes difficult to detect by divination spells such as clairaudience/clairvoyance and spells with the word “detect” in their names."},"obfuscate_drift_beacons":{"name":"Obfuscate Drift Beacons","level":6,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Obfuscate%20Drift%20Beacons","src":"DC pg. 123","summary":"You obscure the Drift beacons in your current star system, making it more difficult to travel to that system. For the duration of the spell, the system takes 2d6 additional days to reach for the purposes of Drift travel to that system."},"omnitool":{"name":"Omnitool","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Omnitool","src":"GM pg. 78","summary":"While you hold the touched object, it transmutes into tools you need for Engineering checks. This tool provides no bonuses to Engineering checks, but it prevents you from taking a penalty for lacking a tool. If the transmuted object leaves your grasp, it reverts to normal."},"optimize_technology":{"name":"Optimize Technology","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Optimize%20Technology","src":"COM pg. 138","summary":"You expend 1 Resolve Point to render a vehicle or technological device immune to corrosive atmospheres, water, heat, radiation, and other natural environmental dangers. If the target regains Hit Points while affected, its Hit Points are restored to their maximum."},"orient":{"name":"Orient","level":3,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Orient","src":"GM pg. 78","summary":"You focus on your surroundings, from the ground beneath your feet to the skies high above, gaining supernatural insight about your place on the planet."},"osmose":{"name":"Osmose","level":2,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Osmose","src":"GM pg. 79","summary":"Initially developed by impatient bantrid students, this spell has grown in popularity among those that want to consume a lot of information quickly. You touch one object and concentrate on a single data set contained within the object, such as a story, email, file, video, or website."},"overheat":{"name":"Overheat","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Overheat","src":"CRB pg. 367","summary":"You collect the heat generated by nearby bodies and devices and vent it outward in a thermal wave, dealing 2d8 fire damage to creatures and objects in the area."},"overload_systems":{"name":"Overload Systems","level":4,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Overload%20Systems","src":"CRB pg. 368","summary":"By touching the target (usually requiring a melee attack roll against the target’s EAC, but you can add your key ability score modifier instead of your Strength modifier if it is higher), you flood the target’s body with random jolts of electricity or other interference."},"parallel_form":{"name":"Parallel Form","level":2,"school":"ill","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Parallel%20Form","src":"COM pg. 138","summary":"You pluck details from alternate-reality versions of targets to weave parallel forms, making the targets appear and act differently. You affect the targets as if they were each under a disguise self spell, deciding the details when you cast this spell."},"paranoia":{"name":"Paranoia","level":2,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Paranoia","src":"AP #10 pg. 53","summary":"The target treats all other creatures as enemies and only itself as an ally. It must attempt attacks of opportunity whenever any creature provokes them. In addition, the target is Shaken while adjacent to more than one creature."},"parasitic_lifelink":{"name":"Parasitic Lifelink","level":3,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Parasitic%20Lifelink","src":"EN pg. 123","summary":"You siphon some of the healing energy that would otherwise affect the target. Whenever the target regains Hit Points, they instead regain only half as many Hit Points (rounded up), and you gain the other half (rounded down)."},"passwall":{"name":"Passwall","level":5,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Passwall","src":"CRB pg. 368","summary":"You can create a passage through metal, plaster, plastic, stone, or wooden walls, but you can not create one through force fields, starship bulkheads, or other harder materials. The passage is 30 feet deep."},"patch_tech":{"name":"Patch Tech","level":1,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Patch%20Tech","src":"COM pg. 139","summary":"You gain a +3 insight bonus to Engineering checks to arm explosives, disable devices, and repair items."},"perfect_hindsight":{"name":"Perfect Hindsight","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Perfect%20Hindsight","src":"EN pg. 124","summary":"You form a subtle mental link between yourself and the targets, enabling the targets to analyze and learn from your future errors."},"perfect_recall":{"name":"Perfect Recall","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Perfect%20Recall","src":"COM pg. 139","summary":"The target is able to recall memories with perfect clarity. If the target has been subjected to displace memory, modify memory, or a similar effect, this spell provides no recall of those lost memories. However, the target realizes its memories have been altered by such a spell or effect."},"personal_gravity":{"name":"Personal Gravity","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Personal%20Gravity","src":"NS pg. 156","summary":"You alter gravity’s effects on you. You treat gravity as if it were your choice of 1 step higher or lower (for example, if you were in an area of low gravity, you could choose either standard gravity or zero-g). You can suppress or resume this affect as a reaction or swift action."},"petal_storm":{"name":"Petal Storm","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Petal%20Storm","src":"AP #42 pg. 43","summary":"You conjure a 5-foot storm of leaves and flower petals from another world, magically honing their edges to be sharp as razors. You create the storm in a square within range and can take a move action to move it up to 30 feet in any direction."},"phantasmal_maze":{"name":"Phantasmal Maze","level":3,"school":"ill","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Phantasmal%20Maze","src":"IS pg. 95","summary":"You create an illusion of a complex maze that creatures in the area perceive. The maze matches the terrain and decor of the area it’s cast in. Those within it perceive walls, doors, barriers, twists, turns, and constant, confusing obstructions."},"phantom_cycle":{"name":"Phantom Cycle","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Phantom%20Cycle","src":"COM pg. 139","summary":"You conjure a motorcycle out of raw magic. This phantom cycle is only partially real, with a shadowy finish, dark trim, and tires of ghostly mist. Only you can pilot this cycle, although anyone can be a passenger."},"phase_blade":{"name":"Phase Blade","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Phase%20Blade","src":"AA4 pg. 73","summary":"You infuse the weapon with magic, allowing you to phase the weapon in and out of existence to partially bypass armor. For the duration of the spell, attacks made with the weapon target EAC, even if the weapon deals kinetic damage."},"physical_stability":{"name":"Physical Stability","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Physical%20Stability","src":"GM pg. 79","summary":"Drawing upon the order and stability of the lawful outer planes, you stabilize a creature’s form with a touch. The target gains a +2 circumstance bonus against transmutation spells and effects. Physical stability counters Baleful Polymorph and Polymorph, and it counters and negates Fluidity Of Form."},"physical_stability_mass":{"name":"Physical Stability, Mass","level":5,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Physical%20Stability%2C%20Mass","src":"GM pg. 79","summary":"This spell functions like Physical Stability, except as noted above Physical Stability Drawing upon the order and stability of the lawful outer planes, you stabilize a creature’s form with a touch. The target gains a +2 circumstance bonus against transmutation spells and effects."},"pinpoint_navigation":{"name":"Pinpoint Navigation","level":3,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Pinpoint%20Navigation","src":"COM pg. 139","summary":"You focus your mind on time and space around you, gaining supernatural insight about your physical place in the universe. You gain a +10 bonus to Piloting checks to navigate and astrogate, and you can plot a course in half the normal time."},"planar_barrier":{"name":"Planar Barrier","level":6,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Planar%20Barrier","src":"CRB pg. 368","summary":"Planar barrier seals an area against all planar travel into or within it. This includes all teleportation spells, summoning spells, plane shifting, astral travel, and ethereal travel. Such effects simply fail automatically."},"planar_binding":{"name":"Planar Binding","level":4,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Planar%20Binding","src":"CRB pg. 369","summary":"Casting this spell attempts a dangerous act: to lure a creature from another plane to a specifically prepared trap, created by the spell within its range. The called creature is held in the trap until it agrees to perform one service in return for its freedom or breaks free."},"planar_phase":{"name":"Planar Phase","level":4,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Planar%20Phase","src":"DC pg. 139","summary":"You open and step through an extraplanar detour that teleports you to any unoccupied space within the spell’s range, as perdimension door. Choose one of the following damage types: acid, bludgeoning, cold, electricity, or fire."},"plane_shift":{"name":"Plane Shift","level":6,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Plane%20Shift","src":"CRB pg. 369","summary":"You move yourself or some other creature to another plane of existence or alternate dimension. If several willing or unconscious creatures are linked by hand in a circle, as many as eight can be affected by a single casting of plane shift."},"planned_obsolescence":{"name":"Planned Obsolescence","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Planned%20Obsolescence","src":"NS pg. 156","summary":"You transform a weapon or suit of armor into an antique version of itself, giving it the analog and archaic properties. Any technological or hybrid armor upgrades cease to function for the duration of the spell. Entirely magical enhancements, such as weapon fusions, continue to function normally."},"plasma_snare":{"name":"Plasma Snare","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Plasma%20Snare","src":"GM pg. 79","summary":"You conjure a volatile string of plasma and lash the target. Attempt a melee attack against the target’s EAC. If you hit, the target takes 3d6 electricity and fire damage (critical knockdown) and is entangled (escape DC equals the spell’s save DC + 4)."},"plurality_strike":{"name":"Plurality Strike","level":6,"school":"div","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Plurality%20Strike","src":"EN pg. 124","summary":"You briefly split your personal timeline into three paths. As part of casting this spell, you make a melee or ranged attack. Make the attack roll three times, note each roll’s result, and use the highest."},"pocket_vacuum":{"name":"Pocket Vacuum","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Pocket%20Vacuum","src":"DC pg. 123","summary":"The affected area becomes a vacuum (Starfinder Core Rulebook294). Creatures take 3d6 bludgeoning damage from decompression (unless they were already in vacuum) and 1d6 bludgeoning damage per round, and they begin suffocating."},"polar_vortex":{"name":"Polar Vortex","level":3,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Polar%20Vortex","src":"NS pg. 156","summary":"You generate an arctic storm of harsh winds and battering hail and snow. Creatures that enter or start their turn in the area during the first round of the spell take 3d6 cold damage plus 6d6 bludgeoning damage and are affected by freezing, hurricane-strength winds."},"polymorph":{"name":"Polymorph","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Polymorph","src":"AA2 pg. 145","summary":"You change a willing target’s shape into a predetermined polymorphed form of your choice. When you select this spell as a spell known, you design four polymorphed forms for each spell level at which you can cast this spell."},"polymorph_mass":{"name":"Polymorph, Mass","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Polymorph%2C%20Mass","src":"AA2 pg. 146","summary":"This spell functions as polymorph, except as noted in this description. Each target must take the same form. 4th: This spell can transform the targets as per the 1st-level version of polymorph. 5th: This spell can transform the targets as per the 2nd-level version of polymorph."},"predict_foe":{"name":"Predict Foe","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Predict%20Foe","src":"COM pg. 139","summary":"You reach into the target’s mind, extracting a sense of its immediate intentions. For the duration, you can warn a creature the target intends to attack, providing that creature with concealment against the attack."},"prescience":{"name":"Prescience","level":3,"school":"div","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Prescience","src":"COM pg. 139","summary":"You peer into the future of multiple realities, collating and perceiving actions the target is likely to take. When that target takes an action during the duration, as a reaction you can execute one of the following effects."},"preserve_specimen":{"name":"Preserve Specimen","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Preserve%20Specimen","src":"COM pg. 23","summary":"You harmlessly render a willing or unconscious living creature inert, placing it in stasis where it does not need to eat, breathe, or sleep. The creature cannot attack, use any abilities, or move while affected by preserve specimen, nor does the creature age or change in any way."},"preserved_path":{"name":"Preserved Path","level":1,"school":"ill","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Preserved%20Path","src":"IS pg. 95","summary":"For the duration of the spell, moving causes you to leave behind a faint illusory string in the spaces you move through; the string follows the path of your center of gravity, emits dim light to a range of 5 feet, and lasts until the end of the spell."},"pressurize":{"name":"Pressurize","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Pressurize","src":"AP #36 pg. 53","summary":"You increase the water pressure in pressurize’s area, dealing 2d10 bludgeoning damage to creatures that enter or start their turn in the area; this damage isn’t reduced as a result of being underwater. Succeeding at the saving throw reduces damage by half."},"private_sanctum":{"name":"Private Sanctum","level":5,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Private%20Sanctum","src":"CRB pg. 369","summary":"This spell ensures privacy. Anyone looking into the area from outside sees only a dark, foggy mass. Darkvision cannot penetrate it. No sounds, no matter how loud, can escape the area, so nobody can eavesdrop from outside. Those inside can see out normally."},"probability_prediction":{"name":"Probability Prediction","level":3,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Probability%20Prediction","src":"CRB pg. 369","summary":"You open your mind to read the underlying probability of the universe. At any point during the duration of this spell, you can discharge it to reroll any one of your d20 rolls (attack roll, saving throw, skill check, etc.); see page 243."},"propelled_leap":{"name":"Propelled Leap","level":2,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Propelled%20Leap","src":"SA:RR pg. 59","summary":"You magically propel yourself through the air to a space within range. Select an empty space within close range (25 feet plus 5 feet per two levels). You’re catapulted into the air and land in that space without harm."},"prowling_junkbot":{"name":"Prowling Junkbot","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Prowling%20Junkbot","src":"AP #25 pg. 53","summary":"This spell functions as the Handy Junkbot spell, but instead creates a stealthy drone that can investigate and spy, transmitting what it sees back to you."},"proximity_alert":{"name":"Proximity Alert","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Proximity%20Alert","src":"GM pg. 79","summary":"You ward an area to alert you when creatures enter without your permission. When you cast proximity alert, select a password."},"prying_eyes":{"name":"Prying Eyes","level":5,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Prying%20Eyes","src":"CRB pg. 370","summary":"You create 20 semitangible, visible magical orbs called “eyes.” These eyes move out, scout around, and return as you direct them when casting the spell. Each eye can see 120 feet (normal vision only) in all directions. While the individual eyes are quite fragile, they’re small and difficult to spot."},"psychic_intuition":{"name":"Psychic Intuition","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Psychic%20Intuition","src":"EN pg. 125","summary":"You draw insights from the target’s memories and emotions. This doesn’t provide you specific information, but it primes your mind to read the target’s mannerisms, feelings, and tells."},"psychic_sonar":{"name":"Psychic Sonar","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Psychic%20Sonar","src":"IS pg. 63","summary":"You project a sonar-like blast of psychic energy that rebounds a moment later. Creatures in the spell’s area each attempt a Will save."},"psychic_surgery":{"name":"Psychic Surgery","level":6,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Psychic%20Surgery","src":"CRB pg. 370","summary":"Psychic surgery heals the target of all Intelligence, Wisdom, and Charisma damage, and it restores all points permanently drained from the target’s Intelligence, Wisdom, and Charisma scores. It also eliminates all ongoing Confusion, fear, and insanity effects."},"psychokinetic_hand":{"name":"Psychokinetic Hand","level":0,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Psychokinetic%20Hand","src":"CRB pg. 370","summary":"You point your finger at the target object, gaining the ability to lift it and move it at will from a distance. As a move action, you can propel the object as far as 15 feet in any direction, though the spell ends if the distance between you and the object ever exceeds the spell’s range."},"psychokinetic_shove":{"name":"Psychokinetic Shove","level":0,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Psychokinetic%20Shove","src":"GM pg. 79","summary":"A targeted creature takes 1 damage with the force description unless it succeeds at a Reflex saving throw. A creature that takes the damage is also subjected to a bull rush. Attempt the bull rush combat maneuver, using your caster level + your key ability score modifier as your attack bonus."},"psychokinetic_strangulation":{"name":"Psychokinetic Strangulation","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Psychokinetic%20Strangulation","src":"CRB pg. 370","summary":"You manipulate the mystical energy around a creature’s throat into a viselike grip, potentially choking the life out of your victim. Each round you concentrate on this spell, it deals 3d8 bludgeoning damage and immobilizes the target."},"puncture_veil":{"name":"Puncture Veil","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Puncture%20Veil","src":"COM pg. 140","summary":"You grasp onto a space-time filled with microscopic needles and use them to pierce into your reality. One creature takes 1d4 piercing damage and gains Bleeding 1 for 3 rounds. You can cast this spell as a full action. If you do, you have two options."},"pyre_wreath":{"name":"Pyre Wreath","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Pyre%20Wreath","src":"AP #18 pg. 53","summary":"This spell creates a circle of three fist-sized orbs of flame around the target creature. The orbs increase the light level by one step within a 10-foot-radius of the target."},"quick_change":{"name":"Quick Change","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Quick%20Change","src":"AP #27 pg. 45","summary":"Adjacent creatures who are unaware of your true form are Flat-footed until the beginning of their next turn. You can cast this spell if you are attacked, or if you attack. If you have the shapechanger subtype or are benefiting from a polymorph effect, you revert to your true form."},"quick_change_(galactic_magic)":{"name":"Quick Change (Galactic Magic)","level":0,"school":"ill","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Quick%20Change%20%28Galactic%20Magic%29","src":"GM pg. 80","summary":"You change the appearance of armor and clothing you wear, provided it all weighs no more than 3 bulk. A creature that interacts with you can attempt a Will saving throw to recognize the illusion."},"radiation_ray":{"name":"Radiation Ray","level":5,"school":"nec","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Radiation%20Ray","src":"GM pg. 80","summary":"You fire a beam of radiation at an opponent. You must attempt a ranged attack against your opponent’s EAC, adding your key ability score modifier instead of your Dexterity modifier if it’s higher. On a hit, the target takes 8d12 fire damage and is exposed to high radiation."},"raise_dead":{"name":"Raise Dead","level":5,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Raise%20Dead","src":"CRB pg. 370","summary":"You restore life to a deceased creature. You can raise a creature that has been Dead for no longer than 1 day per caster level. In addition, the target’s soul must be free and willing to return."},"rapid_overload":{"name":"Rapid Overload","level":6,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rapid%20Overload","src":"EN pg. 125","summary":"You implant a devastating trap into a computer, causing it to overload when operated. The next time a creature attempts to operate the computer, the interface shocks a 30-foot-radius spread, dealing 10d10 electricity damage to all creatures in the area, Stunning them, and knocking them Prone."},"rapid_repair":{"name":"Rapid Repair","level":5,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rapid%20Repair","src":"CRB pg. 371","summary":"On each round, the target construct or weapon regains 2d8 Hit Points. This does not stack with any fast healing the construct or weapon already has. You can’t target a construct or weapon that has been brought to 0 Hit Points or destroyed."},"ray_of_exhaustion":{"name":"Ray Of Exhaustion","level":3,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ray%20Of%20Exhaustion","src":"CRB pg. 371","summary":"You create an enervating ray of magic. You must make a ranged attack against your opponent’s EAC. On a hit, the target is immediately Exhausted for the spell’s duration."},"read_the_flames":{"name":"Read the Flames","level":4,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Read%20the%20Flames","src":"AP #18 pg. 53","summary":"While casting this spell, you must focus on a semi-controlled flame (such as one produced by a lighter or a weapon with the flaming weapon fusion), centering your mind and analyzing the blaze’s movements for subtle patterns that describe the underlying fundamentals of the universe."},"realign":{"name":"Realign","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Realign","src":"GM pg. 80","summary":"You magically right a creature that’s disoriented while floating in a zero-gravity environment. If the target has the Off-Kilter condition, that condition ends. This doesn’t prevent the target from regaining the off-kilter condition."},"reality_bend":{"name":"Reality Bend","level":5,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reality%20Bend","src":"COM pg. 140","summary":"You concentrate on overlapping realities and focus them on the target. Once per round, even when it is not your turn, you can move your target up to 10 feet into a space it is willing and able to occupy. This movement can occur only between resolved actions and does not trigger reactions."},"reality_leap":{"name":"Reality Leap","level":2,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reality%20Leap","src":"COM pg. 140","summary":"You open an unstable tear in reality and leap into the unknown, emerging at another nearby but unpredictable point in this version of existence. When you cast this spell, you state the direction you wish to travel, the distance within range, and the specific square in which you’re trying to arrive."},"reanimate":{"name":"Reanimate","level":5,"school":"nec","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reanimate","src":"PW pg. 207","summary":"You can reanimate a Dead construct or destroyed undead creature that has been Dead or destroyed for no longer than 1 day per caster level."},"reanimate_construct":{"name":"Reanimate Construct","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reanimate%20Construct","src":"NS pg. 157","summary":"This spell turns a destroyed construct into a creature that obeys your spoken commands. As a standard action, you can instruct a reanimated construct to either follow you or attack any creature (or type of creature) within 100 feet."},"recall":{"name":"Recall","level":1,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Recall","src":"COM pg. 23","summary":"Once during the duration, as a reaction, you can reroll a failed skill check to recall knowledge."},"recharge":{"name":"Recharge","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Recharge","src":"CRB pg. 372","summary":"You restore up to 10 charges to a battery or 5 charges to a technological item capable of being charged by a battery. Since this spell takes your personal energy, you must spend 1 Resolve Point to cast it. If you recharge a battery, there is a 20% chance the battery is destroyed by the attempt."},"reflecting_armor":{"name":"Reflecting Armor","level":1,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reflecting%20Armor","src":"CRB pg. 372","summary":"You create a shimmering skin-like coating of mystical force that covers your body, allowing you to reflect damage you take back against your attacker."},"regenerate":{"name":"Regenerate","level":6,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Regenerate","src":"CRB pg. 372","summary":"The target’s severed body members (fingers, toes, hands, feet, arms, legs, tails, or even heads of multiheaded creatures), broken bones, and ruined organs (including eyes) grow back."},"reincarnate":{"name":"Reincarnate","level":4,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reincarnate","src":"CRB pg. 372","summary":"When you cast this spell, you bring back a Dead creature in another body, provided that its death occurred no more than 1 week before the casting of the spell and the target’s soul is free and willing to return."},"reject_augmentation":{"name":"Reject Augmentation","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Reject%20Augmentation","src":"AR pg. 148","summary":"You urge the target creature’s natural systems to reassert themselves, causing its body to temporarily reject augmentations that have been installed in its systems. For the spell’s duration, the creature is sickened and can’t use any augmentations that require an action to activate."},"remembrance":{"name":"Remembrance","level":3,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remembrance","src":"GM pg. 80","summary":"Formulated in conjunction with shimmerstone-induced meditation, kothama favor the use of this spell to contemplate the past."},"remote_operation":{"name":"Remote Operation","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remote%20Operation","src":"COM pg. 140","summary":"A holographic duplicate of the target’s controls appears within your reach. If the target has no controls, the spell fails. As part of concentrating on this spell, you (and only you) can use these holocontrols to operate the target as if you were able to touch its actual controls."},"remote_pilot":{"name":"Remote Pilot","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remote%20Pilot","src":"GM pg. 80","summary":"You transfer a sliver of your consciousness into a vehicle, enabling you to take actions to pilot it remotely. During the spell’s duration, you can pilot the vehicle as if you were in it, except you can use your Mysticism skill to pilot the vehicle in place of Piloting."},"remove_affliction":{"name":"Remove Affliction","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remove%20Affliction","src":"CRB pg. 373","summary":"You remove impurities from a creature or object, potentially neutralizing the curses, Diseases, infestations, Poisons, and other harmful conditions affecting it."},"remove_condition":{"name":"Remove Condition","level":2,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remove%20Condition","src":"CRB pg. 373","summary":"This spell functions in the same way as lesser remove condition, except you remove any one of the following conditions affecting the target: Frightened, Nauseated, Paralyzed, Shaken, Sickened, or Staggered."},"remove_condition_greater":{"name":"Remove Condition, Greater","level":5,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remove%20Condition%2C%20Greater","src":"CRB pg. 373","summary":"This spell functions as lesser remove condition, except you remove all of the following conditions affecting the target: Cowering, Dazed, Frightened, Nauseated, Panicked, Paralyzed, Shaken, Sickened, Staggered, and Stunned."},"remove_condition_lesser":{"name":"Remove Condition, Lesser","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remove%20Condition%2C%20Lesser","src":"CRB pg. 373","summary":"You remove any one of the following conditions affecting the target: Shaken, Sickened, or Staggered."},"remove_radioactivity":{"name":"Remove Radioactivity","level":4,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Remove%20Radioactivity","src":"CRB pg. 374","summary":"You remove all ongoing effects of radiation from a single target if you succeed at a caster level check ( DC = the DC associated with the radiation effect )."},"repulsing_beacon":{"name":"Repulsing Beacon","level":4,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Repulsing%20Beacon","src":"EN pg. 125","summary":"As you cast this spell, choose a creature type; optionally, you can also choose a subtype. You modify a comm unit, causing it to broadcast an electrical signal that creatures of the chosen type find unbearable."},"resilient_sphere":{"name":"Resilient Sphere","level":4,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Resilient%20Sphere","src":"CRB pg. 374","summary":"A 10-foot-diameter globe of shimmering force encloses the target creature. The sphere contains the target for the spell’s duration. The sphere functions in the same way as a wall of force, except it can be negated by dispel magic. A target inside the sphere can breathe normally."},"resist_radiation":{"name":"Resist Radiation","level":2,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Resist%20Radiation","src":"COM pg. 140","summary":"You protect targets from radiation. They succeed at saving throws against low radiation and radiation sickness with a DC of 13 or lower. If the target has radiation sickness with a saving throw DC of 13 or lower, the sickness’s effects are suppressed for the duration."},"resistant_aegis":{"name":"Resistant Aegis","level":5,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Resistant%20Aegis","src":"CRB pg. 374","summary":"This spell functions as lesser resistant armor, except as indicated above, and the wearers and their gear gain DR 5/— or energy resistance 5 that protects against all five energy types."},"resistant_armor":{"name":"Resistant Armor","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Resistant%20Armor","src":"CRB pg. 374","summary":"This spell functions as lesser resistant armor, but the target and her gear gain DR 10/— or energy resistance 10 that protects against three energy types."},"resistant_armor_greater":{"name":"Resistant Armor, Greater","level":6,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Resistant%20Armor%2C%20Greater","src":"CRB pg. 374","summary":"This spell functions as lesser resistant armor, but the target and her gear gain DR 15/— or energy resistance 15 that protects against four energy types."},"resistant_armor_lesser":{"name":"Resistant Armor, Lesser","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Resistant%20Armor%2C%20Lesser","src":"CRB pg. 374","summary":"Lesser resistant armor grants the target (and its gear) protection from your choice of either kinetic damage or energy damage. If you choose kinetic damage, the target and her gear gain DR 5/— that protects against bludgeoning, piercing, and slashing damage."},"restoration":{"name":"Restoration","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Restoration","src":"CRB pg. 374","summary":"This spell functions as lesser restoration, except it also removes temporary negative levels or 1 permanent negative level. You must spend 5 Resolve Points when casting this spell to remove a permanent negative level."},"restoration_lesser":{"name":"Restoration, Lesser","level":2,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Restoration%2C%20Lesser","src":"CRB pg. 374","summary":"Lesser restoration dispels any magical effects reducing one of the target’s ability scores, or it heals 1d4 temporary ability damage to one of the target’s ability scores."},"restore_consumable":{"name":"Restore Consumable","level":2,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Restore%20Consumable","src":"GM pg. 80","summary":"As a reaction after an ally uses a consumable item (such as a grenade or serum, but not ammunition), you can rewind time to the moment before the item’s use, creating a new copy of the item in its position before use."},"retrocognition":{"name":"Retrocognition","level":5,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Retrocognition","src":"CRB pg. 375","summary":"This spell allows you to gain psychic impressions from past events that occurred in your current location."},"revealing_light":{"name":"Revealing Light","level":2,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Revealing%20Light","src":"EN pg. 125","summary":"You modify the wavelengths emitted by the target, transforming the device into a magical light source for the purpose of piercing supernatural darkness (such as that created by the create darkness universal creature rule)."},"rewire_flesh":{"name":"Rewire Flesh","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rewire%20Flesh","src":"CRB pg. 375","summary":"Like rewriting the code that makes up a computer program, you manipulate the target’s DNA to painfully rewire that target’s biological functions to mimic the cold and rigid processes of a robot."},"rewire_flesh_mass":{"name":"Rewire Flesh, Mass","level":6,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rewire%20Flesh%2C%20Mass","src":"CRB pg. 376","summary":"This functions as rewire flesh, except as stated above. Rewire Flesh Like rewriting the code that makes up a computer program, you manipulate the target’s DNA to painfully rewire that target’s biological functions to mimic the cold and rigid processes of a robot."},"rewrite_time":{"name":"Rewrite Time","level":0,"school":"uni","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rewrite%20Time","src":"GM pg. 81","summary":"You unknit the fabric of time and remake it to suit your will. Arewrite timespell can produce one of the following effects Duplicate any precog spell of 6th level or lower. Duplicate any other spell of 5th level or lower. Undo the harmful effects of certain spells, such as feeblemind."},"rhapsodic_aegis":{"name":"Rhapsodic Aegis","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rhapsodic%20Aegis","src":"GM pg. 81","summary":"Rhapsodic aegis, a spell devised by the battle musicians of ancient Pulonis, allows its caster to compose sonic energy into a protective barrier. Casting this spell grants you and each ally within range sonic resistance 5 and 10 temporary Hit Points."},"ride_the_wave":{"name":"Ride The Wave","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Ride%20The%20Wave","src":"DC pg. 123","summary":"You briefly become a miniature River Between, coursing across the landscape in an instant. When you cast this spell, you transform into a stream of water and can move up to 120 feet with a supernatural fly speed (perfect maneuverability)."},"rocket_dash":{"name":"Rocket Dash","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rocket%20Dash","src":"SA:RR pg. 59","summary":"You briefly transform into a rocket of flame and blast forward, moving in a straight line and dealing 5d6 fire damage to all creatures and objects in the line, and then you reappear at the end of the line."},"rocket_dash_greater":{"name":"Rocket Dash, Greater","level":5,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rocket%20Dash%2C%20Greater","src":"SA:RR pg. 59","summary":"This spell functions like Rocket Dash, except it deals 11d6 fire damage to all creatures in the line. On a failed saving throw, a creature additionally gains the Burning condition for 1d6 points of fire damage."},"rotting_touch":{"name":"Rotting Touch","level":1,"school":"nec","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Rotting%20Touch","src":"EN pg. 126","summary":"With a touch, you apply a voracious acid to the target, causing their body to decay, rust, or crumble rapidly. This requires a successful melee attack against the target’s EAC, and casting this spell doesn’t provoke attacks of opportunity."},"scan_environment":{"name":"Scan Environment","level":1,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Scan%20Environment","src":"COM pg. 23","summary":"You analyze the naturally occurring environment in the area, learning the state of the atmosphere, biomes, and gravity. You do not learn the location of or direction to these conditions, only their presence. However, after concentrating for a time, you can learn the following additional information."},"school_spirit":{"name":"School Spirit","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=School%20Spirit","src":"AP #30 pg. 53","summary":"In your time of need, you call upon a spirit of your school to help you. The spirit might manifest as a famous graduate of your school, your school’s mascot, your school’s symbol, or just the specter of a terrifying professor; regardless, the spirit’s ghostly appearance demoralizes your foes."},"secret_locker":{"name":"Secret Locker","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Secret%20Locker","src":"AP #32 pg. 53","summary":"You banish a storage container—such as a backpack, chest, or trunk—to a random location on the Ethereal Plane. The container must be no larger than 1 cubic foot per caster level, can have contents of up to 1 bulk per 2 caster levels, and can contain no sentient creatures."},"security_protocol":{"name":"Security Protocol","level":6,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Security%20Protocol","src":"COM pg. 140","summary":"You protect one building or starship you are within by outfitting it with various technological and magical effects."},"security_seal":{"name":"Security Seal","level":2,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Security%20Seal","src":"CRB pg. 376","summary":"A security seal spell magically locks a single door, container with a lid or latch, portal, or computer system. Casting this spell requires you to spend 1 Resolve Point. You can freely bypass your own security seal without affecting it."},"see_invisibility":{"name":"See Invisibility","level":2,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=See%20Invisibility","src":"CRB pg. 376","summary":"You can see any invisible or ethereal objects or beings within your range of vision, as if they were normally visible. Such creatures are visible to you as translucent shapes, allowing you easily to discern the difference between visible and invisible or ethereal creatures."},"seeking_shot":{"name":"Seeking Shot","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Seeking%20Shot","src":"PW pg. 207","summary":"You create a spiritual link between a weapon you touch and one target you can perceive with a precise sense at the time of casting. The next attack made with that weapon against that target (as long as it is within 1 minute) ignores cover and concealment."},"selective_invisibility":{"name":"Selective Invisibility","level":3,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Selective%20Invisibility","src":"AP #35 pg. 55","summary":"Upon casting this spell, you turn invisible, as Invisibility, and you choose a second target. That creature can still see you as though you weren’t invisible, and you can attack that creature without ending the invisibility effffect. If you attack any other creature, this spell ends."},"shades_of_the_past":{"name":"Shades of the Past","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shades%20of%20the%20Past","src":"EN pg. 126","summary":"You conjure haunting ghosts of a forgotten past into the area. When you cast the spell, you can direct the ghosts to harass one creature in the affected area, giving that creature the Shaken condition for 1 round (Will negates); this is a fear effect."},"shadow_body":{"name":"Shadow Body","level":5,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shadow%20Body","src":"AP #10 pg. 53","summary":"You transform the matter of your body and any objects you carry or wear into the essence of the Shadow Plane."},"shadow_jump":{"name":"Shadow Jump","level":4,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shadow%20Jump","src":"AP #12 pg. 53","summary":"Your body forms a connection to the Shadow Plane, allowing you to teleport through it, rather than the Astral Plane, with ease. While this spell is active, as a move action, you can teleport to any area of dim light or darkness you can see within range."},"shadow_walk":{"name":"Shadow Walk","level":6,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shadow%20Walk","src":"CRB pg. 376","summary":"To use shadow walk, you must be in an area of dim light. You and any creature or vehicle you touch are then transported along a coiling path of shadowstuff to the edge of the Material Plane where it borders the Plane of Shadow. The effect is largely illusory, but the path is quasi-real."},"shadowy_fleet":{"name":"Shadowy Fleet","level":6,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shadowy%20Fleet","src":"CRB pg. 376","summary":"You create a powerful vision of a fleet of hostile starships overhead that appears to rain fiery laser shots mercilessly at your enemies. The ships appear to be 1,000 feet overhead and target a 60-foot-radius area that you designate on the ground."},"share_language":{"name":"Share Language","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Share%20Language","src":"CRB pg. 376","summary":"For 24 hours, the target can read, understand, and communicate to the best of its ability in up to three languages that you already know. This doesn’t change the physical nature of the creature (if it lacks a means of speech, it still can’t talk) or its attitude toward you."},"share_memory":{"name":"Share Memory","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Share%20Memory","src":"COM pg. 141","summary":"You allow the target to share a memory with you and up to five other creatures, all of whom must be willing and within 30 feet of the target when you cast this spell. You designate which memories the target shares when you cast this spell, although the target can guide you in this designation."},"shared_evolution":{"name":"Shared Evolution","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shared%20Evolution","src":"AP #29 pg. 45","summary":"You must be a barathu to learn this spell. When you cast it, you activate your early stage adaptation while also extending it to your allies."},"shared_gravity":{"name":"Shared Gravity","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shared%20Gravity","src":"GM pg. 81","summary":"Copaxis understand personal gravity adaptation well, and they and others have learned to share this adaptation. For the duration, you radiate a field of altered gravity."},"sharpen_senses":{"name":"Sharpen Senses","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sharpen%20Senses","src":"GM pg. 81","summary":"The target gains a +3 insight bonus to Perception checks and blindsight (hearing or scent as determined by the caster) for the duration of the spell. If the target already has blindsight for the sense chosen, the range of their blindsight is instead doubled for the duration of the spell."},"shield_other":{"name":"Shield Other","level":2,"school":"abj","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shield%20Other","src":"CRB pg. 377","summary":"This spell wards the target and creates a mystic connection between you and the target so that some of its wounds are transferred to you. Casting this spell requires you to spend 1 Resolve Point."},"shifting_shadows":{"name":"Shifting Shadows","level":3,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shifting%20Shadows","src":"AP #35 pg. 55","summary":"Waves of shifting shadows obscure the appearance of creatures caught within the emanation, making it harder to tell friends from foes."},"shifting_surge":{"name":"Shifting Surge","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shifting%20Surge","src":"COM pg. 141","summary":"You touch a willing creature and affect one of its energy damage attacks or weapons, changing the energy damage type of one of its attacks to one other type until the end of your next turn."},"shrapnel_shot":{"name":"Shrapnel Shot","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shrapnel%20Shot","src":"EN pg. 126","summary":"You rapidly construct and launch a volatile projectile at a foe, damaging from the impact just before the projectile explodes. Attempt an attack against a target’s KAC; you can add your key ability score modifier to this attack roll instead of your Dexterity modifier if it’s higher."},"shrink_object":{"name":"Shrink Object","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Shrink%20Object","src":"COM pg. 29","summary":"You shrink the target item, transmuting it into a smaller version of itself. You can target an attended object only if the creature attending the object is willing, and you cannot target worn objects. While shrunken, the object takes up less space and bulk, but it can’t be used or worn."},"slice_reality":{"name":"Slice Reality","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Slice%20Reality","src":"COM pg. 141","summary":"You expose targets to churning entropy which turns parts of their body sickly and black. Each target takes 2d6 damage. A successful Fortitude save halves this damage. You can focus on only one target rather than multiple."},"slip_through_space":{"name":"Slip Through Space","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Slip%20Through%20Space","src":"SA:RR pg. 59","summary":"You tear open two temporary rifts, one beneath you and one 10 feet in the air above your intended destination within range. You fall into the rift beneath you and out the exit rift, landing without harm as the rifts close."},"slithering_chain":{"name":"Slithering Chain","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Slithering%20Chain","src":"AP #12 pg. 53","summary":"You call forth a chain from the Shadow Plane, causing it to burst out from the ground and attempt to hinder a target within the spell’s range. The chain attempts a trip combat maneuver against the target; its attack bonus is equal to your base attack bonus + your key ability score modifier + 4."},"slow":{"name":"Slow","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Slow","src":"CRB pg. 377","summary":"An affected creature moves and attacks at a drastically slowed rate. Creatures affected by this spell are Staggered (see page 277) and can take only a single move action or standard action each turn, but not both, and it can’t take full actions."},"smog_bank":{"name":"Smog Bank","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Smog%20Bank","src":"COM pg. 141","summary":"You create a noxious cloud similar to fog cloud that is harmful to living creatures. Smog bank obscures sight just as fog cloud does."},"sniper's_edge":{"name":"Sniper's Edge","level":5,"school":"div","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sniper%27s%20Edge","src":"GM pg. 82","summary":"Made popular by sarcesian snipers, this spell allows you to peer a split second into the future to line up a perfect shot. The next time you attempt an attack with a ranged weapon before the end of this turn, roll your attack twice and keep the better result."},"snuff_life":{"name":"Snuff Life","level":6,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Snuff%20Life","src":"CRB pg. 377","summary":"You twist the essence of life that flows through your targets, snuffing the spark out of weaker creatures and debilitating or disabling others. This spell’s effects depend on each target’s CR. A creature of CR 5 or lower is slain by this spell."},"social_reset":{"name":"Social Reset","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Social%20Reset","src":"GM pg. 82","summary":"You can recover from social blunders and cultural misinterpretations so quickly, as if they never happened. When you fail a Culture check to recall information, or a Diplomacy check to change attitude or gather information, you can cast this spell to reroll the failed check."},"song_of_the_cosmos":{"name":"Song Of The Cosmos","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Song%20Of%20The%20Cosmos","src":"COM pg. 141","summary":"You thrum a discordant tune that underlies existence and hints at the deep secrets of the universe. Creatures in the area must succeed at a Will saving throw or be fascinated for the duration."},"song_of_the_cosmos_greater":{"name":"Song Of The Cosmos, Greater","level":4,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Song%20Of%20The%20Cosmos%2C%20Greater","src":"COM pg. 141","summary":"As song of the cosmos, except as noted above, and creatures that fail their Will saves are also Dazzled for the duration. Song Of The Cosmos You thrum a discordant tune that underlies existence and hints at the deep secrets of the universe."},"sonic_scream":{"name":"Sonic Scream","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sonic%20Scream","src":"GM pg. 82","summary":"Developed by kalo explorers as a deterrent when dealing with aquatic predators, you scream at your opponents, sending your voice rippling through air and water currents. All targets in the cone take 6d12 damage."},"soothing_protocol":{"name":"Soothing Protocol","level":4,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Soothing%20Protocol","src":"CRB pg. 377","summary":"Waves of calming programming ebb from your touch, potentially stabilizing a construct’s harmful intentions toward you and your allies. The target construct must have a CR lower than your level; if it does, the construct is convinced that you and your allies pose no threat."},"soul_reap":{"name":"Soul Reap","level":4,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Soul%20Reap","src":"AA4 pg. 91","summary":"You engulf an area in a comet-like spiral of energy, untethering the souls or animating vital essence from undead in the area. Each undead creature in the area takes 10d8 damage and is Staggered for 1 round."},"soul_surge":{"name":"Soul Surge","level":1,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Soul%20Surge","src":"GM pg. 82","summary":"Soul surge was innovated by Hanakan mystics concomitant with the attunement of their soulstones. With this spell, you draw forth a tiny bit of your essence to attack your opponent, losing a number of Hit Points equal to the number of damage dice you roll for your soul surge."},"spark":{"name":"Spark","level":0,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spark","src":"GM pg. 82","summary":"You agitate molecules within the surface of the object you touch, causing it to catch fire if it’s flammable and the atmosphere allows combustion. This spell can’t cause substances within closed containers, such as the fuel in a petrol tank, to ignite."},"speak_with_dead":{"name":"Speak with Dead","level":3,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Speak%20with%20Dead","src":"CRB pg. 378","summary":"You grant the semblance of life to a corpse, allowing it to answer questions. You can ask up to six questions. The corpse’s knowledge is limited to what it knew during life, including the languages it spoke."},"spell_redirection":{"name":"Spell Redirection","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spell%20Redirection","src":"IS pg. 131","summary":"When an ally within range is targeted by a non-harmless spell or spell-like ability, you can redirect the spell so it targets you instead. Spell redirection fails if you’re immune to the triggering spell’s effects."},"spider_climb":{"name":"Spider Climb","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spider%20Climb","src":"CRB pg. 378","summary":"The target can climb and travel on vertical surfaces or even traverse ceilings as well as a spider does. An affected creature with four limbs must have three limbs free (not holding equipment or being used to perform skills and so on) to climb in this manner."},"spirit-bound_armor":{"name":"Spirit-bound Armor","level":1,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spirit-bound%20Armor","src":"COM pg. 141","summary":"You divert a benevolent spirit from the River of Souls to temporarily inhabit a suit of armor. The spirit steadies the nerves and balance of the creature wearing the armor. If the target becomes Flat-footed during the duration, it ignores the penalty to AC that condition imposes."},"spirit-bound_computer":{"name":"Spirit-bound Computer","level":1,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spirit-bound%20Computer","src":"COM pg. 142","summary":"You divert a benevolent spirit from the River of Souls to inhabit a computer. You can communicate with the spirit while you concentrate; the spirit is trained in Computers and can make Computers checks you request with a total bonus equal to 3 + your caster level + your key ability score modifier."},"spiritual_bonds":{"name":"Spiritual Bonds","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spiritual%20Bonds","src":"GM pg. 82","summary":"Dwarves call on their ancestors to cast this spell of traditional sharing of burdens. This spell connects you and allies in the area on a spiritual level. Each target gains a +1 morale bonus to saving throws."},"spiritual_consultation":{"name":"Spiritual Consultation","level":1,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spiritual%20Consultation","src":"TR pg. 27","summary":"You draw a spirit into a comm unit or computer, allowing you to consult the spirit for information. As a swift action, you can ask the spirit a question; you can ask a question in this way a number of times equal to your key ability score modifier."},"spiritual_minion":{"name":"Spiritual Minion","level":4,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Spiritual%20Minion","src":"EN pg. 127","summary":"Drawing upon your own magical essence, you create a Tiny magical spirit to assist you. The spirit takes any appearance you desire, and is imbued with a fragment of your intelligence and personality, including the ability to speak any languages you know."},"sprout":{"name":"Sprout","level":0,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sprout","src":"AP #42 pg. 43","summary":"You speed the growth of a seed you touch, causing it to instantly sprout. If you plant this sprouted seed in a suitable environment, the seed continues to live, growing at its normal pace. Otherwise, the sprout withers and dies over the course of 1d4 days."},"stabilize":{"name":"Stabilize","level":0,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Stabilize","src":"CRB pg. 378","summary":"If the target of this spell has 0 Hit Points and is Dying, it automatically stabilizes. If the creature later takes damage, it is no longer Stable."},"star_storm":{"name":"Star Storm","level":6,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Star%20Storm","src":"COM pg. 142","summary":"Stellar plasma rains down in the area, dealing 6d8 electricity damage and 6d8 fire damage to creatures and objects in the area."},"star_touch":{"name":"Star Touch","level":6,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Star%20Touch","src":"GM pg. 82","summary":"You attempt to form a miniature star's core inside your target. Choose a point that adjoins the target’s space and is within your reach. Then, attempt a melee attack against the target’s EAC, adding the higher of your key ability modifier or your Strength modifier to the attack roll."},"star_wall":{"name":"Star Wall","level":6,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Star%20Wall","src":"GM pg. 83","summary":"An immobile, vertical curtain of glowing, electromagnetically charged gas springs into existence. The wall raises the light level to bright within 20 feet of it, raises the light level to normal within 20 more feet, and raises the light level one step (up to normal) within 20 more feet."},"starlit_span":{"name":"Starlit Span","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Starlit%20Span","src":"PoC pg. 123","summary":"You conjure a sparkling bridge made of quintessence from the Astral Plane. The bridge is 10 feet wide and connects one point you touch to another point within close range."},"starwalk":{"name":"Starwalk","level":0,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Starwalk","src":"GEM pg. 114","summary":"You can better control your movement in zero gravity. As a swift action, you can cast this spell to end the off-kilter condition gained from movement in zero gravity. If you cast this spell as a move action, you can move up to half your speed in zero gravity."},"status":{"name":"Status","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Status","src":"CRB pg. 379","summary":"When you need to keep track of comrades who get separated, status allows you to mentally monitor their relative positions and general conditions."},"stop_heart":{"name":"Stop Heart","level":6,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Stop%20Heart","src":"EN pg. 127","summary":"You paralyze the target’s heart, causing intense pain and weakness. When you cast this spell, and each round thereafter that you concentrate to sustain the spell while in range, the target takes 5d6 damage and is Dazed for 1 round."},"storm-deflecting_sphere":{"name":"Storm-Deflecting Sphere","level":3,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Storm-Deflecting%20Sphere","src":"IS pg. 123","summary":"You surround yourself with an intangible crystalline sphere that grants you electricity resistance 10 for the spell’s duration."},"stumble":{"name":"Stumble","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Stumble","src":"GM pg. 83","summary":"You momentarily transpose the position of the limbs the target is using to move or interfere with its proprioception. If the target fails its Reflex save, it’s off-target and can move at only half speed for 1 round. A flying creature also descends 10 feet."},"subjective_reality":{"name":"Subjective Reality","level":6,"school":"ill","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Subjective%20Reality","src":"CRB pg. 379","summary":"Choose one object or creature you can see within long range (400 feet + 40 feet/level). You alter your perceptions to become convinced the target is an illusion. For you, the target becomes transparent and does not create sound or smell."},"subzero_clutch":{"name":"Subzero Clutch","level":5,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Subzero%20Clutch","src":"GM pg. 83","summary":"A sleeve of ice encases your striking limb. Attempt a melee attack against the target’s EAC. On a hit, the target takes 10d8 cold damage and moves at half speed for the duration."},"sudden_collision":{"name":"Sudden Collision","level":5,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sudden%20Collision","src":"SA:RR pg. 59","summary":"You pull a high-speed race from another world into your own, superimposing it onto the area. Enemies in the area are struck by passing vehicles, which deftly swerve around objects and your allies. Each enemy in the area takes 7d6 bludgeoning damage."},"suggestion":{"name":"Suggestion","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Suggestion","src":"CRB pg. 379","summary":"You influence the actions of the target creature by suggesting a course of activity (limited to a sentence or two). The suggestion must be worded in such a manner as to make the activity sound reasonable."},"suggestion_mass":{"name":"Suggestion, Mass","level":6,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Suggestion%2C%20Mass","src":"CRB pg. 379","summary":"This spell functions as suggestion, except it can affect more creatures. All of the affected creatures are subject to the same suggestion. Suggestion You influence the actions of the target creature by suggesting a course of activity (limited to a sentence or two)."},"summon_corpse":{"name":"Summon Corpse","level":6,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Summon%20Corpse","src":"GM pg. 83","summary":"You summon the body of a deceased creature that has been dead for no longer than 1 day per caster level from its current position to your side. Deceased creatures up to Large size can be summoned from any location, on any plane, regardless of the current state of their body."},"summon_creature":{"name":"Summon Creature","level":1,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Summon%20Creature","src":"AA1 pg. 144","summary":"This spell summons an extraplanar creature (typically an elemental, magical beast native to another plane, or outsider, but also occasionally even extraplanar constructs). The summoned creature appears where you designate and acts immediately on your turn."},"summon_drift_beacons":{"name":"Summon Drift Beacons","level":6,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Summon%20Drift%20Beacons","src":"NS pg. 157","summary":"You conjure several Drift beacons into your current star system. The beacons appear orbiting the star or stars at various distances but are not in danger of colliding with any other celestial bodies."},"supercharge_armor":{"name":"Supercharge Armor","level":2,"school":"abj","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Supercharge%20Armor","src":"NS pg. 157","summary":"You supercharge the target armor. The armor’s hardness doubles; the armor sheds light in a 20-foot radius, increasing the light level 1 step to a maximum of normal light; and the creature wearing the armor gains temporary Hit Points equal to 5 + your caster level as long as it wears the armor."},"supercharge_weapon":{"name":"Supercharge Weapon","level":1,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Supercharge%20Weapon","src":"CRB pg. 379","summary":"You supercharge the target weapon. If the weapon’s next attack hits (provided it is made before the end of the next round), the attack deals 4d6 additional damage if the weapon is a single target attack or 2d6 additional damage if the weapon attacks all creatures in an area."},"suppressing_field":{"name":"Suppressing Field","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Suppressing%20Field","src":"GM pg. 83","summary":"You create a field of dampening magic, which radiates from a creature or an object and moves with that target. If you target a point, the effect is stationary. Any spell cast into or from this area is subjected to all the effects of a 2nd-level version of Dampen Spell."},"surface_transfer":{"name":"Surface Transfer","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Surface%20Transfer","src":"EN pg. 127","summary":"As a move action while this spell is active, you can physically meld with a solid, physical surface you’re in direct contact with and emerge from another solid surface within 30 feet to which you have line of sight from the point you entered."},"sustaining_shelter":{"name":"Sustaining Shelter","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sustaining%20Shelter","src":"AP #42 pg. 43","summary":"You gently coax the surrounding terrain into a defensive dome capable of protecting you from harmful environments. This simple shelter has a single entrance, no doors, and occupies a 10-ft. cube."},"swap_initiative":{"name":"Swap Initiative","level":1,"school":"abj","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Swap%20Initiative","src":"GM pg. 84","summary":"You sift through the threads of this timeline and rearrange them to your liking."},"swim":{"name":"Swim","level":1,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Swim","src":"AP #36 pg. 53","summary":"You magically enhance one or more targets’ physiologies to allow them to swim through liquids with increasing levels of ease and grace."},"sympathetic_vibration":{"name":"Sympathetic Vibration","level":6,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Sympathetic%20Vibration","src":"CRB pg. 379","summary":"By attuning yourself to a freestanding structure or vehicle (this doesn’t include starships), you can create a damaging vibration within it. Once it begins, the vibration deals 2d10 sonic damage per round to the target, bypassing hardness."},"synapse_overload":{"name":"Synapse Overload","level":5,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Synapse%20Overload","src":"CRB pg. 380","summary":"To affect the target, you must hit with a melee attack against its EAC; you can add your key ability score modifier to this attack roll instead of your Strength modifier if it is higher. You then overload the target’s mind, causing the target’s synapses to violently trigger."},"synaptic_pulse":{"name":"Synaptic Pulse","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Synaptic%20Pulse","src":"CRB pg. 380","summary":"You stun all creatures in range for 1 round."},"synaptic_pulse_greater":{"name":"Synaptic Pulse, Greater","level":5,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Synaptic%20Pulse%2C%20Greater","src":"CRB pg. 380","summary":"You stun all creatures in range for [[//r 1d4]] rounds. With a successful Will saving throw, a creature is instead Sickened for 1 round."},"tectonic_shift":{"name":"Tectonic Shift","level":1,"school":"enc","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Tectonic%20Shift","src":"GEM pg. 75","summary":"You create the sensation of a massive earthquake for a short period of time, causing affected creatures to become unsteady on their feet. 1st: When you cast tectonic shift as a 1st-level spell, you can target a creature within close range (25 feet + 5 feet/2 levels)."},"telekinesis":{"name":"Telekinesis","level":5,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Telekinesis","src":"CRB pg. 380","summary":"You move objects or creatures by concentrating on them. Depending on your desired effect (choose one from below), the spell can perform a variety of combat maneuvers, provide a gentle, sustained force, or exert a single short, violent thrust."},"telekinetic_projectile":{"name":"Telekinetic Projectile","level":0,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Telekinetic%20Projectile","src":"CRB pg. 380","summary":"You fling an object weighing up to 5 pounds (less than 1 bulk) at the target, making a ranged attack against its KAC. If you hit, you deal 1d6 bludgeoning damage to both the target and the object. The type of object thrown doesn’t change the damage type or any other properties of the attack."},"telepathic_bond":{"name":"Telepathic Bond","level":4,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Telepathic%20Bond","src":"CRB pg. 381","summary":"You forge a telepathic bond between yourself and a number of willing creatures, each of which must have an Intelligence score of 3 or higher (or a modifier of –4 or higher). Each creature included in the link is linked to all the others."},"telepathic_jaunt":{"name":"Telepathic Jaunt","level":6,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Telepathic%20Jaunt","src":"CRB pg. 381","summary":"Telepathic jaunt thrums along the mental connection you have with a creature with which you currently have an active telepathic bond via your mystic telepathic bond class feature (but not via the telepathic bond spell), and it instantly teleports you to that creature."},"telepathic_message":{"name":"Telepathic Message","level":0,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Telepathic%20Message","src":"CRB pg. 381","summary":"You can send a short telepathic message and hear simple telepathic replies. Any living creature within 10 feet of you or an intended recipient also receives your telepathic message if it succeeds at a DC 25 Perception check. You must be able to see or hear each recipient."},"telepathy":{"name":"Telepathy","level":5,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Telepathy","src":"CRB pg. 381","summary":"You can mentally communicate with any other creature within 100 feet that has a language."},"teleport":{"name":"Teleport","level":5,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Teleport","src":"CRB pg. 381","summary":"This spell instantly transports you to a designated destination within 2,000 miles. Interplanar and interplanetary travel is not possible, and neither is travel between two moving starships during combat, though you might be able to teleport to a planet’s surface from an orbiting starship."},"temporal_anchor":{"name":"Temporal Anchor","level":4,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Temporal%20Anchor","src":"EN pg. 128","summary":"You create an imperceptible beacon marking your exact point in time and space at that instant. At the end of your next turn, you teleport to that exact spot without spending an action, so long as you are still on the same plane of existence."},"temporal_bullets":{"name":"Temporal Bullets","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Temporal%20Bullets","src":"GM pg. 84","summary":"You rewind time to a moment of missed opportunity and unleash the damage from a failed attack onto the original target of the attack. As a reaction after an ally’s attack with a weapon misses an enemy, you redirect the missed attack’s damage onto that enemy."},"temporal_flash":{"name":"Temporal Flash","level":5,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Temporal%20Flash","src":"GM pg. 84","summary":"You shift positions in your current timeline to avoid damage dealt by an attack."},"temporal_wave":{"name":"Temporal Wave","level":2,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Temporal%20Wave","src":"EN pg. 128","summary":"You project a wave of temporal disruption that batters and disorients all creatures in the area, dealing 3d6 bludgeoning damage and Staggering affected creatures for 1 round."},"tempting_fate":{"name":"Tempting Fate","level":4,"school":"enc","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Tempting%20Fate","src":"EN pg. 128","summary":"You create a magical lure at the center of the affected area, which creatures in the area perceive as either a wondrous temptation or an imminent threat that must be deactivated."},"tenacious_plow":{"name":"Tenacious Plow","level":3,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Tenacious%20Plow","src":"SA:RR pg. 60","summary":"You conjure a magical 10-foot-square vehicle in an unoccupied space within range."},"terraform":{"name":"Terraform","level":6,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Terraform","src":"CRB pg. 382","summary":"You alter the area’s terrain and climate to a new terrain and climate type appropriate to the planet or plane. For example, you might transform a desert into plains."},"thought_ripple":{"name":"Thought Ripple","level":2,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Thought%20Ripple","src":"PoC pg. 123","summary":"You overload a target’s mind with so much psychic stimuli that it ripples to another target, triggering the initial spell as well as overloading the new target with residual psychic overload."},"time's_edge":{"name":"Time's Edge","level":3,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Time%27s%20Edge","src":"GM pg. 84","summary":"You refract latent energy from the Dimension of Time into your current plane in the form of a massive blade. This deals 10d6 slashing damage to all creatures and objects in the area."},"time_bombs":{"name":"Time Bombs","level":4,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Time%20Bombs","src":"EN pg. 128","summary":"You create three time bombs (each an explosive about the size of a datapad) that each instantly adhere to a floor, wall, or similar surface. Each time bomb appears at a grid intersection of your choice within the spell’s range, but each must be at least 15 feet away from each other."},"time_crawl":{"name":"Time Crawl","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Time%20Crawl","src":"GM pg. 84","summary":"You distort time in the area, forcing it to pass slowly. This area is difficult terrain. Creatures in the area when the spell is cast, or who enter the area, are staggered for as long as they remain in the area."},"time_lapse":{"name":"Time Lapse","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Time%20Lapse","src":"EN pg. 128","summary":"You push an object forward or backward through time. When you cast the spell and each subsequent round that you concentrate, you either increase or decrease the target’s age by 1 day."},"time_loop":{"name":"Time Loop","level":2,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Time%20Loop","src":"GM pg. 84","summary":"You immerse a creature in a time loop of your creation. The target sees and reacts to events that no longer coincide with the current timeline, becoming confused for 1 round and entangled for the duration."},"time_loop_mass":{"name":"Time Loop, Mass","level":4,"school":"con","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Time%20Loop%2C%20Mass","src":"GM pg. 84","summary":"This spell functions as Time Loop, except as noted above. Time Loop You immerse a creature in a time loop of your creation. The target sees and reacts to events that no longer coincide with the current timeline, becoming confused for 1 round and entangled for the duration."},"token_spell":{"name":"Token Spell","level":0,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Token%20Spell","src":"CRB pg. 382","summary":"Token spells are often some of the first minor changes that spellcasters produce when they begin experimenting with magic. Once cast, token spell enables you to perform simple magical effects for 1 hour. The effects are minor and have severe limitations. You can slowly lift one item of light bulk."},"tongues":{"name":"Tongues","level":3,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Tongues","src":"CRB pg. 383","summary":"This spell grants the creature touched the ability to speak and understand the spoken or signed language of any intelligent creature, whether it is a racial tongue or a regional dialect. The target can speak only one language at a time, although it may be able to understand several languages."},"tracking_mark":{"name":"Tracking Mark","level":4,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Tracking%20Mark","src":"GM pg. 84","summary":"You place a unique magical mark, which is about 1 square inch in size, on a creature or object. The mark is invisible, but Detect Magic and similar effects can reveal its presence. Unattended objects are always affected by this spell."},"transfer_charge":{"name":"Transfer Charge","level":0,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Transfer%20Charge","src":"CRB pg. 383","summary":"You can transfer any number of charges from one battery to another battery or from one power cell to another power cell."},"transfer_consciousness":{"name":"Transfer Consciousness","level":5,"school":"div","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Transfer%20Consciousness","src":"COM pg. 142","summary":"You transfer your mind into a computer or technological construct. If you transfer your mind into a computer, its tier can be no higher than half your caster level. If you transfer into a construct, it must be willing or, if nonsapient, not hostile to you."},"transfer_time":{"name":"Transfer Time","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Transfer%20Time","src":"EN pg. 129","summary":"You transfer crucial seconds from yourself to nearby creatures. Each ally in the area gains an additional move action on their next turn to take a Guarded Step, move up to their speed, or Draw or Sheathe a Weapon."},"translocate_object":{"name":"Translocate Object","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Translocate%20Object","src":"AP #42 pg. 43","summary":"You instantly transfer an object held in your hand to the hand of a willing creature within range. The object can be no heavier than 1 bulk. The creature you teleport the object to must have at least one empty hand to hold the object."},"transport_passengers":{"name":"Transport Passengers","level":4,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Transport%20Passengers","src":"COM pg. 142","summary":"You create an extradimensional space in the passenger area of a vehicle or Tiny starship, allowing it to carry one additional Medium creature per caster level. This spell must be cast on a vehicle able to carry more than one passenger, or the spell fails."},"true_seeing":{"name":"True Seeing","level":6,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=True%20Seeing","src":"CRB pg. 383","summary":"You confer upon the target the ability to see all things within 120 feet as they actually are."},"umbral_tendrils":{"name":"Umbral Tendrils","level":3,"school":"ill","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Umbral%20Tendrils","src":"AP #12 pg. 53","summary":"You summon a vision of a writhing mass of shadowy tendrils to assault creatures within 10 feet of the ground in the area. This area is difficult terrain."},"uncanny_eruption":{"name":"Uncanny Eruption","level":4,"school":"evo","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Uncanny%20Eruption","src":"GEM pg. 75","summary":"You form the crater of an active volcano at a target location, immediately exposing all creatures in the area to lava (Core Rulebook 403), dealing 2d6 fire damage immediately, and continuing to expose creatures who begin their turn in the area, who take the appropriate fire damage at the beginning…"},"uncanny_luck":{"name":"Uncanny Luck","level":2,"school":"div","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Uncanny%20Luck","src":"GM pg. 85","summary":"Mimicking the luck of halflings, you presciently react or tug on the strands of fate, casting this spell just after a d20 roll you attempt for a saving throw or an enemy attempts for an attack against you."},"undo_mistake":{"name":"Undo Mistake","level":5,"school":"div","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Undo%20Mistake","src":"GM pg. 85","summary":"Frequently used by formian taskmasters to assist with training workers in new fields or avoiding costly mistakes, this spell has become popular among educators, managers, parents, and mentors of all kinds."},"unfettered":{"name":"Unfettered","level":3,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Unfettered","src":"EN pg. 129","summary":"You partially untether an ally from the flow of time, enabling them to perform minor tasks with remarkable speed."},"unmask":{"name":"Unmask","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Unmask","src":"GM pg. 85","summary":"Embri cast this spell to shame other embri who break decorum, and precogs manifest this spell by revealing a creature’s true future appearance."},"unravel_magic":{"name":"Unravel Magic","level":5,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Unravel%20Magic","src":"GM pg. 85","summary":"You unravel the magic imbuing a magic item, permanently removing its magical properties. To do so, you must attempt a caster level check (1d20 + your caster level). The DC equals 11 + the item’s level, or 5 + a consumable item’s level."},"unseen_servant":{"name":"Unseen Servant","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Unseen%20Servant","src":"CRB pg. 383","summary":"The spell conjures an invisible, mindless, shapeless force that performs simple tasks at your command (a move action). It can run and fetch things, open unstuck doors, and hold chairs, as well as clean and mend."},"unspeakable_presences":{"name":"Unspeakable Presences","level":6,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Unspeakable%20Presences","src":"COM pg. 142","summary":"You swap the space beneath your enemies with the gnashing maws, tentacles, and claws of hideous beasts from another reality. A foe in the area takes 4d6 damage per round and cannot move until it succeeds at a Reflex saving throw, which it can attempt at the end of each of its turns."},"unwilling_guardian":{"name":"Unwilling Guardian","level":5,"school":"enc","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Unwilling%20Guardian","src":"CRB pg. 383","summary":"Your overwhelming presence bores into the target’s mind, cowing its will. This turns it into an automaton-like guardian that protects you at all costs."},"update_tech":{"name":"Update Tech","level":1,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Update%20Tech","src":"EN pg. 129","summary":"You transform the target, rapidly updating its components and mechanisms to modern design standards for the spell’s duration. If the target has the Archaic weapon special property, it temporarily loses that property."},"usher_apocalypse":{"name":"Usher Apocalypse","level":6,"school":"ill","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Usher%20Apocalypse","src":"COM pg. 142","summary":"You create a quasi-real apocalypse to tear through the area, causing several effects. When the spell first takes effect, illusory hellfire crashes to the ground, dealing 6d6 fire damage to your enemies in the area."},"usurp_spell":{"name":"Usurp Spell","level":4,"school":"abj","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Usurp%20Spell","src":"GM pg. 85","summary":"You override the will of another spellcaster, taking control of their spell. As a reaction when you observe a spell being cast within range, you can cast this spell. If you do, you can attempt a dispel check (1d20 + your caster level)."},"vanishing_trick":{"name":"Vanishing Trick","level":0,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Vanishing%20Trick","src":"GM pg. 85","summary":"The object you touch becomes invisible."},"varied_veneer":{"name":"Varied Veneer","level":0,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Varied%20Veneer","src":"GM pg. 85","summary":"You make the object you touch appear to be broken or otherwise worthless, or you make a broken object appear to be functional. A creature that handles the object can attempt a Will saving throw to recognize the illusion."},"veil":{"name":"Veil","level":6,"school":"ill","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Veil","src":"CRB pg. 384","summary":"You instantly change the appearance of the targets and then maintain that appearance for the spell’s duration. You can make the targets appear to be anything you wish. The targets look, feel, and smell just like what the spell makes them resemble."},"venomous_weapon":{"name":"Venomous Weapon","level":2,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Venomous%20Weapon","src":"COM pg. 23","summary":"You touch a weapon that deals bludgeoning, piercing, or slashing damage and imbue it with Poison. The next five attacks made using the weapon are poisoned. Each creature damaged by these attacks must succeed at a Fortitude save or be sickened for 2d4 rounds."},"verdant_blast":{"name":"Verdant Blast","level":2,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Verdant%20Blast","src":"AP #42 pg. 43","summary":"Tapping into the life-giving energy of your home world, you emit a blast of rapidly growing roots, branches, vines, and thorns that puncture creatures in a line, dealing 3d6 piercing damage to all creatures and objects in the area."},"verdant_code":{"name":"Verdant Code","level":1,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Verdant%20Code","src":"NS pg. 129","summary":"You turn data into plant matter that either instantly explodes outward or lurks within a device. Instant Growth: You immediately incite growth from the targeted device. A creature can negate the effect on an object it holds with a successful Will save or with spell resistance."},"vigilant_junkbot":{"name":"Vigilant Junkbot","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Vigilant%20Junkbot","src":"COM pg. 143","summary":"You turn the target into a robot that can guard you. This spell works like handy junkbot insofar as targeting parameters and your inability to target the same equipment after the spell ends. The junkbot you create is Tiny and appears in your space. A vigilant junkbot can take no actions."},"viral_destruction":{"name":"Viral Destruction","level":3,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Viral%20Destruction","src":"AP #2 pg. 51","summary":"You can cast this spell only immediately after a creature in range dies."},"vision":{"name":"Vision","level":6,"school":"div","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Vision","src":"CRB pg. 384","summary":"You pose a question about some person, place, or object while casting this spell. If the person or object is at hand or if you are in the place in question and you succeed at a caster level check ( 1d20 + your caster level, DC 20 ), you receive a vision about that person, place, or object."},"void_grasp":{"name":"Void Grasp","level":4,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Void%20Grasp","src":"GM pg. 86","summary":"Reaching to worlds beyond, you siphon your foe’s life force as a shared offering to some extraplanar entity. Attempt a melee attack against the target’s EAC, adding the higher of your key ability modifier or your Strength modifier to the attack roll."},"void_vessel":{"name":"Void Vessel","level":2,"school":"trs","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Void%20Vessel","src":"DC pg. 123","summary":"You grant one or more targets the ability to survive in vacuum. Affected targets gain the Void Adaptation (Ex or Su) universal creature rule and sprout wings of pure energy that grant a supernatural fly speed of 60 feet (average maneuverability) that functions only in vacuum."},"void_whispers":{"name":"Void Whispers","level":3,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Void%20Whispers","src":"GEM pg. 115","summary":"The target’s mind is flooded with elder mysteries from the dark between the stars, galaxies, and dimensions. The target must attempt a Will save; on a failure, it begins whispering incoherently and moves half its speed in a random direction."},"volcanic_wrath":{"name":"Volcanic Wrath","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Volcanic%20Wrath","src":"IS pg. 115","summary":"You summon an erupting volcano that unleashes molten rock over an area, dealing fire and bludgeoning damage. The eruption leaves molten rocks, thick ash, and smoke, making the entire area of effect difficult terrain for the duration of the spell."},"wall_of_air":{"name":"Wall Of Air","level":3,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Air","src":"AP #36 pg. 53","summary":"You cause a massive sheet of flowing air to appear. When you cast wall of air, choose whether the air flows upward or downward. This spell has different effects depending on the environment in which it is cast (below)."},"wall_of_earth":{"name":"Wall Of Earth","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Earth","src":"GM pg. 86","summary":"An earthen barrier springs into existence, anchored to surrounding solid surfaces or, at least, supported by a firm foundation. The stress of casting this spell requires you to spend 1 Resolve Point."},"wall_of_fire":{"name":"Wall Of Fire","level":4,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Fire","src":"CRB pg. 384","summary":"An immobile blazing curtain of opaque, shimmering, violet fire springs into existence. One side of the wall, selected by you, sends forth waves of heat, dealing 2d6 fire damage to creatures within 10 feet and 1d6 fire damage to those beyond 10 feet but within 20 feet."},"wall_of_fog":{"name":"Wall Of Fog","level":1,"school":"ill","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Fog","src":"GM pg. 86","summary":"A billowing wall of dense mist forms in a vertical plane, provided the wall is neither underwater nor in a vacuum. In those cases, the spell fails. Creatures and objects on one side of the wall have concealment (20% miss chance) from creatures on the opposite side of the wall."},"wall_of_force":{"name":"Wall Of Force","level":5,"school":"evo","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Force","src":"CRB pg. 384","summary":"Wall of force creates an invisible wall of pure force. You can form the wall into a flat, vertical plane whose area is up to one 10-foot square per level. The wall must be continuous and unbroken when formed. If its surface is broken by any object or creature, the spell fails."},"wall_of_ice":{"name":"Wall Of Ice","level":3,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Ice","src":"GM pg. 86","summary":"An icy barrier, your choice of a plane or hemisphere, springs into existence. A plane can be oriented in any fashion, provided it’s anchored. If vertical, the wall needs only a solid foundation; a horizontal or slanting wall must be anchored on two opposite sides."},"wall_of_steam":{"name":"Wall Of Steam","level":2,"school":"con","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Steam","src":"GM pg. 86","summary":"This spell functions as Wall of Fog, except you can select one side of the wall to give off searing steam. Creatures within 5 feet of this side of the wall take 2d4 fire damage, and those beyond 5 feet but within 10 feet take 1d4 fire damage."},"wall_of_steel":{"name":"Wall Of Steel","level":6,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Steel","src":"CRB pg. 385","summary":"You cause a flat, vertical steel wall to spring into existence. The stress of casting this spell requires you to spend 1 Resolve Point. The wall can fit into any space of surrounding nonliving material if its area is sufficient to do so."},"wall_of_stone":{"name":"Wall Of Stone","level":4,"school":"con","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20Of%20Stone","src":"AP #17 pg. 58","summary":"You cause a flat, vertical stone wall to spring into existence. The stress of casting this spell requires you to spend 1 Resolve Point. The wall can fit into any space of surrounding nonliving material if its area is sufficient to do so."},"wall_of_warped_time":{"name":"Wall of Warped Time","level":2,"school":"trs","allowedClasses":{"myst":false,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wall%20of%20Warped%20Time","src":"EN pg. 129","summary":"You create a faint vertical field that warps time and space. The wall is insubstantial, remains in place once created, and doesn’t need to anchor to a surface."},"warp_reality":{"name":"Warp Reality","level":6,"school":"uni","allowedClasses":{"myst":false,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Warp%20Reality","src":"COM pg. 143","summary":"Beckoning to all realities at once, you pull in new possibilities and alter your world to suit you. A warp reality spell can produce one of the following effects. Duplicate any witchwarper spell of 6th level or lower. Duplicate any other spell of 5th level or lower."},"warpwave":{"name":"Warpwave","level":3,"school":"trs","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Warpwave","src":"AA4 pg. 87","summary":"You blast your target with the ripples of myriad realities, causing it to transform in unpredictable ways that are typically temporary."},"wave_of_warning":{"name":"Wave Of Warning","level":5,"school":"evo","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wave%20Of%20Warning","src":"GM pg. 87","summary":"Maraquoi spellcasters developed this spell to deter sapient aggressors from bloodshed. You thrust a wave of mental determination at up to three targets, attempting a ranged attack against each target’s KAC to deal 10d8 nonlethal bludgeoning damage."},"waves_of_fatigue":{"name":"Waves Of Fatigue","level":5,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Waves%20Of%20Fatigue","src":"CRB pg. 385","summary":"Waves of negative energy render all living creatures in the spell’s area fatigued. This spell has no effect on a creature that is already fatigued."},"weight_of_ages":{"name":"Weight Of Ages","level":5,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Weight%20Of%20Ages","src":"GM pg. 87","summary":"You burden the targets with all the aches, pains, and sorrows of a lifetime. The targets take 10d8 damage and become encumbered for the duration, or they become overburdened if already encumbered."},"wish":{"name":"Wish","level":6,"school":"uni","allowedClasses":{"myst":false,"tech":true,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wish","src":"CRB pg. 385","summary":"By simply speaking aloud, you can alter reality to better suit you. Even wish, however, has its limits. A wish spell can produce any one of the following effects. Duplicate any technomancer spell of 6th level or lower. Duplicate any other spell of 5th level or lower."},"wisp_ally":{"name":"Wisp Ally","level":1,"school":"con","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wisp%20Ally","src":"CRB pg. 385","summary":"You draw forth otherworldly energy to create a small, spherical, floating wisp that can distract your enemies in combat. This wisp can move 60 feet per round in any direction, and you can direct it as a move action on your turn."},"wither":{"name":"Wither","level":4,"school":"nec","allowedClasses":{"myst":true,"tech":false,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wither","src":"EN pg. 129","summary":"You drain the moisture and vitality from your surroundings. Living creatures and organic objects in the area take 6d12 damage. Creatures with the plant type or water subtype take a –2 penalty on their saving throw against this spell."},"wonder_warp":{"name":"Wonder Warp","level":4,"school":"evo","allowedClasses":{"myst":true,"tech":true,"precog":false,"wysh":true},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Wonder%20Warp","src":"GEM pg. 115","summary":"You alter the magical forces in the area near you into an unpredictable field of eldritch entropy, potentially causing a number of effects both positive and negatives for those who find themselves in the area."},"x-ray_vision":{"name":"X-Ray Vision","level":4,"school":"div","allowedClasses":{"myst":true,"tech":true,"precog":true,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=X-Ray%20Vision","src":"GM pg. 87","summary":"You confer upon the target sense through (vision) with a range of 60 feet."},"zone_of_truth":{"name":"Zone Of Truth","level":2,"school":"enc","allowedClasses":{"myst":true,"tech":false,"precog":false,"wysh":false},"modifiers":[],"aon":"https://www.aonsrd.com/SpellDisplay.aspx?ItemName=Zone%20Of%20Truth","src":"CRB pg. 385","summary":"Creatures within the emanation area can’t speak any deliberate and intentional lies. Each potentially affected creature can attempt a Will saving throw to avoid the effect when the spell is cast or when that creature first enters the emanation area."}}};
  if (typeof module !== 'undefined') module.exports = part; else root.SFDATA = Object.assign(root.SFDATA || {}, part);
})(this);
